// Üretilen dosya: tool/ozgun/uret.py. Biyoloji · Kalıtım, genetik ve evrim (orta).
const ozBiology2Orta = <(String, String, List<String>, String)>[
  ('Bezelyenin Mendel\'in deneyleri için uygun olmasının nedenlerinden biri aşağıdakilerden hangisidir?', 'Kendi kendini döllemesinin kolayca denetlenebilmesi', ['Kromozom sayısının çok yüksek olması', 'Tohumlarının yalnızca rüzgârla uzak bölgelere dağılabilmesi', 'Her nesilde yalnız bir tohum vermesi'], 'Bezelye çiçeği kapalı yapıda olduğundan doğal olarak kendi kendini döller; Mendel çiçekleri açıp yapay tozlaşma yaparak çaprazlamaları denetleyebilmiştir. Ayrıca kısa sürede çok sayıda döl verir.'),
  ('Mendel\'in çalışmalarının 1900 yılında birbirinden bağımsız olarak yeniden keşfedilmesine katkı sağlayan bilim insanlarından biri kimdir?', 'Hugo de Vries', ['Thomas Hunt Morgan', 'Charles Darwin', 'James Watson'], '1900\'de Hugo de Vries, Carl Correns ve Erich von Tschermak, Mendel\'in yasalarını bağımsız olarak yeniden buldu.'),
  ('Mendel\'in ayrılma (segregasyon) ilkesine göre aşağıdakilerden hangisi doğrudur?', 'Bir karakterin iki aleli gamet oluşumunda farklı gametlere ayrılır.', ['Farklı karakterlere ait genler her zaman birlikte kalıtılır.', 'Çekinik aleller birkaç nesil sonra yok olur.', 'Bir bireyin her geni yalnızca tek bir alelle temsil edilir ve ayrılmaz.'], 'Ayrılma ilkesine göre diploit bireydeki bir gen çiftinin alelleri gamet oluşurken birbirinden ayrılır ve her gamete yalnız biri geçer.'),
  ('Heterozigot (Aa) bir bireyde çekinik a alelinin etkisinin fenotipte görülmemesinin nedeni aşağıdakilerden hangisidir?', 'Baskın alelin etkisinin fenotipte kendini göstermesi', ['a alelinin hiçbir zaman RNA\'ya kopyalanamaması', 'a alelinin gamete aktarılmaması', 'a alelinin kromozomdan kopması'], 'Baskın alel tek kopya hâlinde bile fenotipi belirler; çekinik alel genotipte vardır ve gametlere aktarılabilir ama fenotipe yansımaz.'),
  ('"Taşıyıcı" olarak nitelendirilen bir birey için aşağıdakilerden hangisi doğrudur?', 'Çekinik bir hastalık alelini taşır ancak hastalığı göstermez.', ['Hastalığın baskın alelini iki kopya hâlinde taşır.', 'Hastalığı gösterir fakat bu aleli çocuklarına hiçbir zaman aktaramaz.', 'Yalnızca mitokondrisinde hastalık geni bulunur.'], 'Taşıyıcı birey çekinik alel için heterozigottur; fenotipi normaldir ama aleli %50 olasılıkla gametlerine aktarır.'),
  ('Fenotipi baskın olan bir bireyin genotipi hakkında aşağıdakilerden hangisi kesin olarak söylenebilir?', 'En az bir baskın alel taşır.', ['Kesinlikle homozigottur.', 'Kesinlikle heterozigottur.', 'Hiçbir gamete çekinik alel aktarmaz.'], 'Baskın fenotip AA ya da Aa genotipinden doğabilir; bu yüzden yalnızca en az bir baskın alel taşıdığı kesindir.'),
  ('Aynı genotipe sahip iki ortanca (hortensia) bitkisinden biri asitli, diğeri bazik toprakta yetiştirildiğinde farklı renkte çiçek açıyor. Bu durum en iyi hangi ifadeyle açıklanır?', 'Fenotip, genotip ile çevrenin etkileşimiyle oluşur.', ['Toprak pH\'ı bitkilerden birinin genotipini kalıcı olarak değiştirmiştir.', 'İki bitkiden biri mutasyona uğramıştır.', 'Çiçek rengi yalnızca kalıtımla belirlenir.'], 'Genotip aynı kaldığı hâlde çevre koşulu fenotipi değiştirmiştir; bu bir modifikasyon örneğidir.'),
  ('Aa × Aa çaprazlamasından doğan bireyler arasında genotip oranı aşağıdakilerden hangisidir?', '1 AA : 2 Aa : 1 aa', ['3 AA : 1 aa', '1 AA : 1 aa', '2 AA : 1 Aa : 1 aa'], 'Her ebeveyn A ve a gametlerini eşit olasılıkla verir; birleşimler 1/4 AA, 2/4 Aa, 1/4 aa olur.'),
  ('Sarı tohum (Y) yeşil tohuma (y) baskındır. Yy × yy çaprazlamasından 200 tohum elde ediliyor. Beklenen yeşil tohum sayısı kaçtır?', '100', ['50', '150', '200'], 'Yy × yy çaprazlamasında yarı yarıya Yy ve yy oluşur; 200 tohumun yarısı, yani 100\'ü yeşildir.'),
  ('Bir çiftliğe ait iki siyah tüylü kobay çaprazlandığında yavrular arasında beyaz tüylü bireyler de çıkıyor. Bu sonuca göre aşağıdakilerden hangisi kesindir?', 'Her iki ebeveyn de heterozigottur.', ['Beyaz renk siyaha baskındır.', 'Ebeveynlerden yalnızca biri beyaz alel taşır.', 'Yavrularda mutasyon olmuştur.'], 'Fenotipi ebeveynlerde görülmeyen beyaz özelliğin ortaya çıkması beyazın çekinik olduğunu ve iki ebeveynin de çekinik alel taşıdığını gösterir.'),
  ('Bağımsız açılan iki gen için heterozigot olan iki bezelye (AaBb × AaBb) çaprazlanıyor. Baskınlık tam ise döllerde beklenen fenotip oranı nedir?', '9 : 3 : 3 : 1', ['3 : 1', '1 : 1 : 1 : 1', '1 : 2 : 1'], 'Her gen ayrı ayrı 3:1 açılım verir; bağımsız açılımda (3:1) × (3:1) = 9:3:3:1 olur.'),
  ('Genotipi AaBbCc olan ve genleri farklı kromozomlarda bulunan bir birey kaç çeşit gamet oluşturabilir?', '8', ['6', '4', '3'], 'Gamet çeşidi 2^n formülüyle bulunur; n heterozigot gen çifti sayısıdır. 2^3 = 8.'),
  ('AaBb × AaBb çaprazlamasında genler bağımsız açılıyorsa aabb genotipli bir döl oluşma olasılığı nedir?', '1/16', ['1/4', '3/16', '1/8'], 'aa olasılığı 1/4, bb olasılığı 1/4\'tür; bağımsız olaylar çarpılır: 1/16.'),
  ('Bağımsız açılan genler için AaBb × Aabb çaprazlaması yapılıyor. Döllerin kaçta kaçı A baskın, B çekinik fenotipte olur?', '3/8', ['3/16', '1/4', '1/8'], 'A_ olasılığı 3/4, bb olasılığı (Bb × bb\'den) 1/2\'dir; 3/4 × 1/2 = 3/8.'),
  ('Mendel\'in bağımsız açılım ilkesi aşağıdakilerden hangisini ifade eder?', 'Farklı karakterlerin alelleri gametlere birbirinden bağımsız dağılır.', ['Bir karakterin iki aleli aynı gamete geçer.', 'Baskın aleller her zaman birlikte kalıtılır.', 'Çekinik aleller yalnızca eşey kromozomlarında bulunur ve ayrı kalıtılır.'], 'Bağımsız açılım ilkesine göre farklı kromozomlardaki gen çiftlerinin alelleri gamet oluşumunda birbirinden bağımsız biçimde dağılır.'),
  ('İki karakter bakımından heterozigot bir bitki kendileştirildiğinde 9:3:3:1 oranı yerine ebeveyn fenotiplerinin çok fazla, yeni birleşimlerin çok az görüldüğü bir sonuç elde ediliyor. Bu durumun en olası nedeni nedir?', 'İki genin aynı kromozomda bağlı olması', ['İki genin farklı kromozomlarda bulunması', 'Çevrenin fenotipi hiç etkilememesi', 'Bitkinin poliploit olmaması'], 'Bağlı genler çoğunlukla birlikte gametlere geçer; yeni birleşimler yalnızca krossing-over ile ve düşük sıklıkta oluşur.'),
  ('Siyah tüylü bir köpek (siyah baskın) beyaz tüylü bir köpekle çiftleştiriliyor ve doğan yavruların yarısı siyah, yarısı beyaz oluyor. Siyah köpeğin genotipi nedir?', 'Heterozigot', ['Homozigot baskın', 'Homozigot çekinik', 'Belirlenemez'], 'Test çaprazlamasında 1:1 açılım görülmesi, baskın fenotipli bireyin heterozigot olduğunu ve iki çeşit gamet verdiğini gösterir.'),
  ('Uzun gövdeli bir bezelye kısa gövdeli bir bezelyeyle çaprazlanıyor ve elde edilen 120 bitkinin tamamı uzun gövdeli çıkıyor. Bu sonuca göre uzun ebeveyn için en makul çıkarım nedir?', 'Büyük olasılıkla homozigot baskındır.', ['Kesinlikle heterozigottur.', 'Kısa gövde alelini taşır.', 'Çekinik alelin yanında yarı baskın bir alel taşır.'], 'Heterozigot olsaydı yaklaşık yarı yarıya kısa döl beklenirdi; 120 dölün hepsinin uzun olması ebeveynin TT olduğunu güçlü biçimde gösterir.'),
  ('AaBb genotipli bir birey aabb ile test çaprazlamasına sokuluyor ve genler bağımsız açılıyor. Döllerde kaç farklı fenotip hangi oranda beklenir?', 'Dört fenotip, 1 : 1 : 1 : 1', ['İki fenotip, 1 : 1', 'Dört fenotip, 9 : 3 : 3 : 1 oranında', 'Üç fenotip, 1 : 2 : 1'], 'AaBb dört çeşit gameti eşit oranda verir; aabb yalnız ab verdiğinden dört fenotip eşit oranda oluşur.'),
  ('Eksik baskınlık gösteren pembe çiçekli iki aslanağzı bitkisi çaprazlandığında döllerde beklenen fenotip oranı nedir?', '1 kırmızı : 2 pembe : 1 beyaz', ['3 pembe : 1 beyaz : 1 kırmızı', '1 kırmızı : 1 beyaz', 'Tamamı pembe'], 'Kırmızı aleli K, beyaz aleli B ise KB × KB çaprazlaması 1 KK : 2 KB : 1 BB verir; eksik baskınlıkta genotip ve fenotip oranları aynıdır.'),
  ('Eksik baskınlıkta F2 dölünde genotip oranı ile fenotip oranının aynı olmasının nedeni nedir?', 'Heterozigotun kendine özgü bir fenotipi olması', ['Çekinik alelin hiç ifade edilmemesi', 'Homozigot bireylerin embriyo evresinde yaşayamaması', 'Alellerin bağlı olması'], 'Heterozigot birey homozigot baskından ayırt edilebildiği için her genotip ayrı bir fenotip sınıfına karşılık gelir.'),
  ('Eksik baskınlık gösteren pembe çiçekli bir bitki beyaz çiçekli bir bitkiyle çaprazlanıyor. Döllerin yüzde kaçı pembe olur?', '%50', ['%25', '%75', '%100'], 'KB × BB çaprazlamasında döllerin yarısı KB (pembe), yarısı BB (beyaz) olur.'),
  ('Eksik baskınlığı eş baskınlıktan ayıran temel özellik aşağıdakilerden hangisidir?', 'Eksik baskınlıkta heterozigot ara fenotip, eş baskınlıkta iki fenotip birlikte görülür.', ['Eksik baskınlıkta F2\'de 3:1, eş baskınlıkta 9:3:3:1 oranı görülür.', 'Eksik baskınlık yalnızca bitkilerde, eş baskınlık yalnızca hayvanlarda görülür.', 'Eş baskınlıkta heterozigot bireyler yaşayamaz.'], 'Pembe aslanağzı ara fenotipe, AB kan grubu ise iki antijenin birlikte bulunmasına örnektir.'),
  ('İnsanda MN kan grubu sisteminde M ve N alelleri eş baskındır. MN kan gruplu iki ebeveynin çocuklarında beklenen fenotip oranı nedir?', '1 M : 2 MN : 1 N', ['3 M : 1 N', 'Tamamı MN kan gruplu', '1 M : 1 N'], 'MN × MN çaprazlaması 1 MM : 2 MN : 1 NN verir; eş baskınlıkta her genotip ayrı fenotip olduğundan oranlar aynıdır.'),
  ('Orak hücre aleli için heterozigot bir kişinin kanında hem normal hemoglobin hem de orak hücre hemoglobini bulunur. Bu durum moleküler düzeyde hangi kavrama uyar?', 'Eş baskınlık', ['Tam baskınlık', 'Letal etki', 'Genomik baskılanma'], 'Heterozigotta iki alelin ürünü olan iki hemoglobin türü de üretilir; protein düzeyinde iki alel birlikte ifade edilir.'),
  ('AB kan gruplu bir kişinin plazmasında aşağıdakilerden hangisi bulunur?', 'Ne anti-A ne de anti-B antikoru', ['Yalnızca anti-A antikoru', 'Yalnızca anti-B antikoru', 'Hem anti-A hem anti-B antikoru'], 'AB grubunda alyuvarlar A ve B antijenlerini taşır; vücut kendi antijenlerine karşı antikor üretmediği için plazmada anti-A ya da anti-B bulunmaz.'),
  ('Genotipi I^A i olan bir anne ile I^B i olan bir babanın çocuklarında kaç farklı kan grubu fenotipi görülebilir?', '4', ['2', '3', '1'], 'Çaprazlamadan I^A I^B (AB), I^A i (A), I^B i (B) ve ii (0) oluşur; her biri 1/4 olasılıktadır.'),
  ('AB kan gruplu bir anne ile 0 kan gruplu bir babanın çocuklarının kan grubu için aşağıdakilerden hangisi doğrudur?', 'A ya da B olabilir.', ['Yalnızca AB olabilir.', 'Yalnızca 0 olabilir.', 'A, B, AB ya da 0 olabilir.'], 'Anne I^A ya da I^B, baba yalnızca i verir; çocuk I^A i (A) ya da I^B i (B) olur. AB için iki ebeveynden A ve B alelleri, 0 için iki i aleli gerekir.'),
  ('Tavşanlarda kürk rengini belirleyen C, c^ch, c^h ve c alelleri bir dizi oluşturur. Bu durum hangi kavrama örnektir?', 'Çok alellilik', ['Poligenik kalıtım', 'Epistasi', 'Bağlı genler'], 'Bir lokusta popülasyonda ikiden fazla alelin bulunmasına çok alellilik denir; bir birey bunlardan en fazla ikisini taşır.'),
  ('Çok alellilik için aşağıdakilerden hangisi doğrudur?', 'Diploit bir birey bu alellerin en fazla ikisini taşıyabilir.', ['Bir birey popülasyondaki bütün alelleri aynı anda taşıyabilir.', 'Aleller farklı kromozomlarda bulunur.', 'Yalnızca eşey kromozomlarında görülür.'], 'Çok alellilik popülasyon düzeyinde bir kavramdır; diploit bireyde her lokus için yalnızca iki alel bulunabilir.'),
  ('Eritroblastozis fetalis (yeni doğanın hemolitik hastalığı) riski en yüksek olan durum hangisidir?', 'Daha önce Rh pozitif bebek doğurmuş Rh negatif annenin yine Rh pozitif bebek taşıması', ['Rh pozitif bir annenin ilk gebeliğinde Rh negatif bir bebek taşıması', 'Anne ve bebeğin ikisinin de Rh negatif olması', 'Rh negatif annenin ilk kez Rh negatif bebeğe gebe kalması'], 'İlk doğumda bebeğin kanıyla karşılaşan Rh negatif anne anti-Rh antikoru üretir; sonraki Rh pozitif gebelikte bu antikorlar plasentayı geçip bebeğin alyuvarlarını yıkar.'),
  ('Rh uyuşmazlığı riski taşıyan annelere doğumdan sonra anti-D (anti-Rh) iğnesi yapılmasının amacı nedir?', 'Annede fetal Rh antijenlerine karşı bağışıklık belleği oluşmasını önlemek', ['Annenin kan grubunu Rh pozitife çevirmek', 'Bebeğin kanındaki antikor miktarını artırarak onu enfeksiyona karşı korumak', 'Annenin alyuvar üretimini hızlandırmak'], 'Verilen hazır antikorlar annenin dolaşımına geçen Rh pozitif fetal hücreleri annenin bağışıklık sistemi bellek oluşturmadan ortadan kaldırır.'),
  ('Rh pozitif bir baba ile Rh negatif bir annenin ilk çocuğu Rh negatif doğuyor. Bu ailenin ikinci çocuğunun Rh pozitif olma olasılığı nedir?', '1/2', ['3/4', '1/4', '1'], 'Rh negatif çocuk babanın heterozigot (Rr) olduğunu gösterir. rr × Rr çaprazlamasında çocuğun Rh pozitif olma olasılığı 1/2\'dir.'),
  ('Bir ailenin üç çocuğunun hepsinin erkek olma olasılığı nedir?', '1/8', ['1/3', '1/4', '3/8'], 'Bağımsız olaylarda olasılıklar çarpılır: 1/2 × 1/2 × 1/2 = 1/8.'),
  ('Genetik olasılık hesaplarında "ve" bağlacıyla ifade edilen iki bağımsız olayın birlikte gerçekleşme olasılığı nasıl bulunur?', 'Olasılıklar çarpılır.', ['Olasılıklar toplanır.', 'Büyük olasılık küçüğe bölünür.', 'Olasılıkların ortalaması alınır.'], 'Bağımsız iki olayın birlikte olma olasılığı çarpım kuralıyla, birbirini dışlayan olaylardan birinin olma olasılığı toplama kuralıyla bulunur.'),
  ('Aa × Aa çaprazlamasında bir dölün AA ya da aa olma olasılığı nedir?', '1/2', ['1/4', '3/4', '1/16'], 'AA ve aa birbirini dışlayan olaylardır; toplama kuralıyla 1/4 + 1/4 = 1/2.'),
  ('Bağlı genler arasında yeni gen birleşimlerinin (rekombinant gametlerin) oluşmasını sağlayan olay hangisidir?', 'Krossing-over', ['Mitoz bölünme', 'Nondisjunction', 'Transkripsiyon'], 'Homolog kromozomların kardeş olmayan kromatitleri arasında parça değişimi bağlı genlerin yeni birleşimler oluşturmasını sağlar.'),
  ('İki bağlı gen arasındaki krossing-over sıklığı ile bu genlerin kromozom üzerindeki uzaklığı arasındaki ilişki nedir?', 'Genler birbirinden uzaklaştıkça krossing-over sıklığı artar.', ['Genler birbirine yaklaştıkça krossing-over sıklığı artar.', 'Krossing-over sıklığı uzaklıktan bağımsızdır.', 'Krossing-over yalnızca birbirine bitişik genler arasında gerçekleşebilir.'], 'İki gen arasındaki mesafe arttıkça aralarında parça değişimi olma olasılığı da artar; gen haritaları bu ilişkiye dayanır.'),
  ('A ve B genleri arasındaki rekombinasyon sıklığı %12 olarak ölçülmüştür. Bu iki genin arasındaki harita uzaklığı kaçtır?', '12 santimorgan', ['24 santimorgan', '6 santimorgan', '88 santimorgan'], '%1 rekombinasyon sıklığı 1 harita birimine (1 cM) karşılık gelir; %12 rekombinasyon 12 cM uzaklığı gösterir.'),
  ('Bir krossing-over deneyinde iki gen arasındaki rekombinasyon sıklığı %50\'ye yakın bulunuyor. Bu sonuç en iyi nasıl yorumlanır?', 'Genler ya farklı kromozomlardadır ya da aynı kromozomda çok uzaktadır.', ['Genler tam bağlıdır ve aralarında hiç krossing-over olmamaktadır.', 'Genler arasındaki uzaklık sıfırdır.', 'Genlerden biri letal etkilidir.'], '%50 rekombinasyon bağımsız açılımla aynı sonucu verir; çok uzak bağlı genlerde de çoklu krossing-over nedeniyle bu değer gözlenir.'),
  ('Kuşlarda eşey belirleme için aşağıdakilerden hangisi doğrudur?', 'Dişiler ZW, erkekler ZZ eşey kromozomuna sahiptir.', ['Dişiler XX, erkekler XY eşey kromozomuna sahiptir.', 'Dişiler ZZ, erkekler ZW eşey kromozomuna sahiptir.', 'Eşey kromozom yoktur; eşey yalnızca kuluçka sıcaklığıyla belirlenir.'], 'Kuşlarda (ve kelebeklerde) ZW sistemi görülür; burada iki farklı eşey kromozomu taşıyan ve eşeyi belirleyen dişidir.'),
  ('Bal arılarında erkek arıların (dronların) döllenmemiş yumurtalardan gelişmesi hangi eşey belirleme sistemine örnektir?', 'Haplodiploidi', ['XY sistemi', 'ZW sistemi', 'Sıcaklığa bağlı eşey belirleme'], 'Bal arılarında döllenmiş (diploit) yumurtalar dişi, döllenmemiş (haploit) yumurtalar erkek olur.'),
  ('Bazı kaplumbağa ve timsah türlerinde yavrunun eşeyi neye bağlı olarak belirlenir?', 'Yumurtaların kuluçka sıcaklığına', ['Babanın taşıdığı eşey kromozomlarına', 'Annenin yaşına', 'Yumurtanın büyüklüğüne'], 'Bu sürüngenlerde eşey kromozomları yoktur; embriyonun belirli bir döneminde yuvadaki sıcaklık eşeyi belirler.'),
  ('Y kromozomu üzerinde bulunan ve embriyonun testis geliştirmesini başlatan gen hangisidir?', 'SRY', ['BRCA1', 'CFTR', 'HBB'], 'SRY geni (Sex-determining Region Y) testis oluşumunu tetikleyen proteini kodlar; bu genin bulunmadığı embriyolar dişi yönde gelişir.'),
  ('Çekirgelerde dişiler XX, erkekler ise tek X kromozomlu (XO) olabilir. Bu tür çekirgelerde erkeğin oluşturduğu spermlerle ilgili hangisi doğrudur?', 'Yarısı X kromozomu taşır, yarısı eşey kromozomu taşımaz.', ['Tamamı X kromozomu taşır.', 'Tamamı Y kromozomu taşır.', 'Yarısı X, yarısı Y kromozomu taşır; eşey kromozomsuz sperm oluşmaz.'], 'XO erkekte tek X kromozomu mayozda spermlerin yarısına gider; diğer yarısında eşey kromozomu bulunmaz.'),
  ('Renk körü bir erkek, renk körlüğü aleli taşımayan bir kadınla evleniyor. Bu çiftin çocukları için hangisi doğrudur?', 'Kızlar taşıyıcı, oğullar sağlıklı olur.', ['Oğulların yarısı renk körü olur.', 'Kızların yarısı renk körü olur.', 'Oğulların tamamı ile kızların yarısı renk körü olur.'], 'Baba X kromozomunu yalnız kızlarına verir, bu yüzden kızların tamamı taşıyıcıdır. Oğullar X\'i sağlam anneden alır.'),
  ('Hemofili taşıyıcısı bir kadın sağlıklı bir erkekle evleniyor. Doğacak bir oğullarının hemofili olma olasılığı nedir?', '1/2', ['1/4', '0', '1'], 'Oğul X kromozomunu anneden alır; anne X^H X^h olduğundan oğlun X^h alma olasılığı 1/2\'dir.'),
  ('X\'e bağlı çekinik bir hastalık için aşağıdaki aktarım biçimlerinden hangisi gerçekleşemez?', 'Hasta babadan oğluna aktarım', ['Taşıyıcı anneden oğluna aktarım', 'Hasta babadan kızına aktarım', 'Taşıyıcı anneden kızına aktarım'], 'Baba oğluna Y kromozomunu verir; X kromozomundaki alel babadan oğula geçmez.'),
  ('Renk körü bir kadın normal görüşlü bir erkekle evleniyor. Çocuklarının fenotipleri için hangisi beklenir?', 'Oğulların tümü renk körü, kızların tümü normal görüşlü olur.', ['Kızların tümü renk körü, oğulların tümü normal görüşlü olur.', 'Çocukların yarısı renk körü olur, eşey fark etmez.', 'Bütün çocuklar normal görüşlü olur ve taşıyıcı değildir.'], 'Anne X^r X^r olduğundan her oğul X^r alır ve renk körüdür. Kızlar babadan X^R aldığı için normal görüşlü ama taşıyıcıdır.'),
  ('Bir ailede hemofili hastası bir erkeğin anne ve babası sağlıklıdır. Bu erkeğin hemofili alelini kimden aldığı kesindir?', 'Annesinden', ['Babasından', 'Anneannesinin babasından', 'Ebeveynlerinin ikisinden de'], 'Erkek tek X\'ini annesinden alır. Anne sağlıklı olduğuna göre taşıyıcıdır.'),
  ('Erkeklerin X kromozomundaki genler için "hemizigot" terimi kullanılır. Bunun anlamı nedir?', 'Bu genlerin yalnızca tek kopyasının bulunması', ['Bu genlerin iki farklı alelinin bulunması', 'Bu genlerin iki özdeş alel hâlinde bulunması', 'Bu genlerin hiç ifade edilmemesi'], 'Erkekte X üzerindeki genlerin çoğunun Y\'de karşılığı yoktur; bu genler tek kopya hâlinde bulunur.'),
  ('Kalıtsal saç dökülmesi (androgenetik kellik) aleli erkeklerde baskın, kadınlarda çekinik etki gösterir. Bu durum hangi kalıtım tipine örnektir?', 'Eşeyin etkilediği kalıtım', ['Eşeye sınırlı kalıtım', 'X kromozomuna bağlı baskın kalıtım', 'Y\'ye bağlı kalıtım'], 'Gen otozomaldir ancak etkisi eşey hormonlarına göre değişir; heterozigot erkekte görülür, heterozigot kadında görülmez.'),
  ('Boğaların da taşıdığı süt verimi genleri yalnızca ineklerde fenotipe yansır. Bu durum hangi kalıtım tipiyle açıklanır?', 'Eşeye sınırlı kalıtım', ['Eşeyin etkilediği kalıtım', 'Y kromozomuna bağlı kalıtım', 'Sitoplazmik kalıtım'], 'Eşeye sınırlı özellikler için gerekli genler iki eşeyde de bulunur ama yalnız bir eşeyde ifade edilir.'),
  ('Bir özelliğin X\'e bağlı mı yoksa eşeyin etkilediği otozomal bir özellik mi olduğunu ayırt etmek için en yararlı gözlem hangisidir?', 'Özelliğin babadan oğula aktarılıp aktarılmadığı', ['Özelliğin yalnızca yetişkinlikte görülüp görülmediği', 'Özelliğin kız çocuklarında hiç görülüp görülmediği', 'Özelliğin çevreden etkilenip etkilenmediği'], 'X\'e bağlı alel babadan oğula geçemez; otozomal bir alel ise geçebilir. Bu nedenle babadan oğula aktarım otozomal kalıtımı gösterir.'),
  ('Bir soyağacında sağlıklı anne ve babanın hasta bir kız çocuğu varsa özellik hangi biçimde kalıtılmaktadır?', 'Otozomal çekinik', ['Otozomal baskın', 'X\'e bağlı çekinik', 'Y\'ye bağlı'], 'Sağlıklı ebeveynden hasta çocuk doğması özelliğin çekinik olduğunu gösterir. Babası sağlıklı olan kızın hasta olması X\'e bağlı çekinikliği dışlar.'),
  ('İki hasta ebeveynin sağlıklı bir çocuğu olduğu görülüyorsa hastalık hakkında hangi sonuç çıkarılır?', 'Hastalık baskın bir alelle belirlenir.', ['Hastalık çekinik bir alelle belirlenir.', 'Hastalık mitokondriyal kalıtılır.', 'Hastalık Y\'ye bağlı kalıtılır.'], 'Çekinik bir özellikte iki hasta ebeveynin (aa × aa) tüm çocukları hasta olurdu; sağlıklı çocuk ebeveynlerin heterozigot baskın olduğunu gösterir.'),
  ('Bir soyağacında hasta bir annenin oğullarından biri sağlıklıdır. Bu bilgi tek başına hangi kalıtım tipini kesin olarak dışlar?', 'X\'e bağlı çekinik', ['Otozomal baskın', 'Otozomal çekinik kalıtım', 'X\'e bağlı baskın'], 'X\'e bağlı çekinik özellikte hasta anne X^a X^a\'dır ve her oğluna X^a verir; sağlıklı oğul bu tipi dışlar.'),
  ('Hasta bir babanın kızlarından biri sağlıklıdır. Bu durum hangi kalıtım tipiyle bağdaşmaz?', 'X\'e bağlı baskın', ['Otozomal baskın', 'Otozomal çekinik', 'X\'e bağlı çekinik'], 'X\'e bağlı baskın özellikte hasta baba X\'ini bütün kızlarına verir ve hepsi hasta olur.'),
  ('Bir özelliğin her kuşakta görüldüğü, iki eşeyde yaklaşık eşit sıklıkta bulunduğu ve babadan oğula aktarılabildiği bir soyağacı en çok hangi kalıtım tipine uyar?', 'Otozomal baskın', ['X\'e bağlı çekinik', 'Otozomal çekinik', 'Mitokondriyal'], 'Kuşak atlamaması baskınlığı, eşeyler arası eşitlik ve babadan oğula aktarım ise otozomal kalıtımı gösterir.'),
  ('Otozomal çekinik bir hastalığı taşıyan biri ile hasta olan biri evleniyor. Çocuklarının hasta olma olasılığı nedir?', '1/2', ['1/4', '3/4', '0'], 'Aa × aa çaprazlamasında döllerin yarısı Aa, yarısı aa olur.'),
  ('Aynı genotipteki tek yumurta ikizlerinden biri iyi, diğeri yetersiz beslenerek büyüdüğünde boylarının farklı olması neyi gösterir?', 'Boy uzunluğunun çevreden de etkilendiğini', ['Boyun yalnızca kalıtımla belirlendiğini', 'İkizlerin genotiplerinin farklı olduğunu', 'Beslenmenin ikizlerden birinin genlerini kalıcı olarak değiştirdiğini'], 'Tek yumurta ikizleri aynı genotipe sahiptir; aralarındaki fark çevre etkisinden kaynaklanır.'),
  ('Belirli bir genotipi taşıyan bireylerin yalnızca bir kısmında beklenen fenotipin ortaya çıkmasını tanımlayan kavram hangisidir?', 'Eksik penetrans', ['Eş baskınlık', 'Hemizigotluk durumu', 'Bağlantı'], 'Penetrans, genotipi taşıyanların ne kadarında fenotipin gözlendiğini gösterir; bu oran %100\'ün altındaysa eksik penetrans söz konusudur.'),
  ('Letal gen kavramı için aşağıdakilerden hangisi doğrudur?', 'Taşıyan bireyin belirli bir genotipte ölümüne yol açan alellerdir.', ['Yalnızca bitkilerde bulunan ve büyümeyi hızlandıran genlerdir.', 'Bireyin ömrünü her koşulda uzatan ve popülasyonda hızla yayılan genlerdir.', 'Bireyin yalnızca rengini belirleyen genlerdir.'], 'Letal aleller genellikle homozigot durumda embriyonik ya da erken dönemde ölüme yol açar.'),
  ('Fareler üzerindeki çalışmalarında ilk kez letal bir aleli (sarı kürk aleli) tanımlayan Fransız bilim insanı kimdir?', 'Lucien Cuénot', ['Louis Pasteur', 'Jean-Baptiste Lamarck', 'Georges Cuvier'], 'Cuénot 1905\'te sarı farelerin çaprazlamalarında beklenen 3:1 yerine 2:1 oranını gözlemledi; bu oran homozigot letaliteyle açıklandı.'),
  ('Huntington hastalığına yol açan baskın alel neden popülasyondan doğal seçilimle kolayca silinmez?', 'Belirtilerin genellikle üreme çağından sonra başlaması', ['Alelin yalnızca erkeklerde bulunması', 'Alelin çekinik olması', 'Hastalığın her zaman çocuklukta öldürmesi'], 'Belirtiler genellikle 30–50 yaşları arasında ortaya çıkar; birey o yaşa kadar çocuk sahibi olmuş olabileceğinden alel kuşaktan kuşağa aktarılır.'),
  ('Bir popülasyonda çekinik letal bir alelin bütünüyle yok olmadan kuşaklar boyunca korunabilmesinin temel nedeni nedir?', 'Heterozigot taşıyıcıların sağlıklı olup aleli aktarabilmesi', ['Homozigot çekinik bireylerin popülasyonda daha fazla yavru bırakabilmesi', 'Alelin yalnızca gametlerde bulunması', 'Çekinik alellerin hiç mutasyona uğramaması'], 'Çekinik letal alel heterozigotlarda fenotipe yansımaz; bu bireyler üreyip aleli sonraki kuşaklara aktarır.'),
  ('Annenin yaşı ilerledikçe trizomili bebek doğma riskinin artmasının en çok kabul gören açıklaması hangisidir?', 'Yumurta hücrelerinde mayoz sırasında ayrılmama olasılığının yaşla artması', ['Babadan gelen spermlerdeki kromozom sayısının annenin yaşıyla birlikte azalması', 'Annenin vücut hücrelerinin hızla mutasyona uğraması', 'Plasentanın kromozom eklemesi'], 'Yumurta öncüllerinde mayoz doğumdan önce başlar ve yıllarca askıda kalır; ilerleyen yaşla kromozomların doğru ayrılmama riski artar.'),
  ('Duplikasyonun evrim açısından önemi en iyi hangi ifadeyle açıklanır?', 'Fazladan gen kopyalarının zamanla yeni işlevler kazanabilmesi', ['Kromozom sayısını her kuşakta yarıya indirerek yeni türlerin oluşmasını sağlaması', 'Bütün genleri işlevsiz bırakması', 'Yalnızca eşey kromozomlarında görülmesi'], 'Bir genin kopyası mutasyonlarla farklılaşıp yeni görev kazanabilir; insandaki globin gen ailesi bu yolla oluşmuştur.'),
  ('Orak hücre anemisinde β-globin zincirinin 6. amino asidi olan glutamik asit yerine hangi amino asit bulunur?', 'Valin', ['Lizin', 'Glisin', 'Triptofan'], 'GAG kodonunun GTG\'ye dönüşmesiyle glutamik asit yerine valin gelir; bu yanlış anlamlı bir nokta mutasyonudur.'),
  ('Somatik hücrelerde oluşan bir mutasyon için hangisi doğrudur?', 'Bireyde etkili olabilir ama eşeyli üremeyle yavrulara aktarılmaz.', ['Yalnızca yavrularda etkili olur.', 'Her zaman bütün vücut hücrelerinde birden bulunur ve hücreleri öldürür.', 'Eşey hücrelerine geçerek mutlaka kalıtılır.'], 'Kalıtsal olan, eşey hücrelerinde ya da onları oluşturan hücrelerde meydana gelen mutasyonlardır; somatik mutasyon bireyle sınırlı kalır.'),
  ('Ultraviyole ışınların DNA\'da en sık oluşturduğu hasar hangisidir?', 'Komşu timinler arasında dimer oluşması', ['Şeker-fosfat omurgasının tamamen çözünmesi', 'Adeninin urasile dönüşmesi', 'Kromozom sayısının iki katına çıkması'], 'UV ışını aynı zincirdeki yan yana iki timin arasında kovalent bağ kurarak timin dimerleri oluşturur; bu yapı eşlenmeyi bozar.'),
  ('Meyve sineklerinde X ışınlarının mutasyon oluşturduğunu göstererek 1946 Nobel ödülünü alan bilim insanı kimdir?', 'Hermann J. Muller', ['Thomas Hunt Morgan', 'Alfred Sturtevant', 'Barbara McClintock'], 'Muller 1927\'de X ışınlarıyla mutasyon sıklığının büyük ölçüde arttığını gösterdi.'),
  ('Bir kimyasalın mutajenik etkisini bakteriler üzerinde hızlıca tarayan ve kanser yapıcı maddelerin ön incelemesinde kullanılan test hangisidir?', 'Ames testi', ['ELISA testi', 'Gram boyama testi', 'Western blot'], 'Ames testi, histidin sentezleyemeyen Salmonella suşlarında maddenin geri mutasyon sıklığını artırıp artırmadığını ölçer.'),
  ('DNA\'nın iki zincirinin "antiparalel" olması ne anlama gelir?', 'Zincirlerin 5\'→3\' yönelimlerinin birbirine zıt olması', ['İki zincirin baz dizisinin aynı ve aynı yönde okunuyor olması', 'İki zincirin birbirine kovalent bağlarla bağlanması', 'Zincirlerden birinin yalnız pürin bazları taşıması'], 'Bir zincir 5\'→3\' yönünde uzanırken karşısındaki zincir 3\'→5\' yönündedir.'),
  ('Bir DNA zincirinin bir bölümünün baz dizisi 5\'-ATGCCA-3\' şeklindedir. Bu bölümün tamamlayıcı zincirinin 5\'→3\' yönünde okunan dizisi hangisidir?', '5\'-TGGCAT-3\'', ['5\'-TACGGT-3\'', '5\'-ATGCCA-3\'', '5\'-ACCGTA-3\''], 'Tamamlayıcı zincir 3\'-TACGGT-5\' olur; bunu 5\'→3\' yönünde yazınca TGGCAT elde edilir.'),
  ('DNA\'nın sarmal yapıda olduğunu gösteren ünlü "Fotoğraf 51" adlı X ışını kırınım görüntüsü hangi bilim insanının laboratuvarında elde edilmiştir?', 'Rosalind Franklin', ['Linus Pauling', 'Erwin Chargaff', 'Frederick Griffith'], 'Franklin ve öğrencisi Raymond Gosling\'in 1952\'de elde ettiği görüntü sarmal yapının kanıtlarından biri oldu.'),
  ('Hershey ve Chase 1952\'de bakteriyofajların proteinlerini radyoaktif kükürtle (³⁵S), DNA\'larını radyoaktif fosforla (³²P) işaretlediler. Bakterilerin içinde yalnızca ³²P bulunması neyi gösterdi?', 'Fajların bakteriye kalıtsal madde olarak DNA\'yı aktardığını', ['Fajların bakteriye kalıtsal madde olarak protein kılıflarını aktardığını', 'Kükürdün DNA\'da bulunduğunu', 'Bakterilerin fosfor içermediğini'], 'Fosfor DNA\'da bulunur, proteinlerde hemen hiç yoktur; kükürt ise proteinlerde bulunur. Hücreye giren ³²P olduğuna göre kalıtsal madde DNA\'dır.'),
  ('Her iki zinciri ¹⁵N içeren tek bir DNA molekülü ¹⁴N içeren ortamda üç kez eşleniyor. Oluşan moleküllerden kaçı hiç ¹⁵N içermez?', '6', ['2', '8', '4'], 'Üç eşlenme sonunda 2³ = 8 molekül oluşur. Orijinal iki ¹⁵N zinciri yalnızca 2 molekülde bulunur; kalan 6 molekül tamamen ¹⁴N\'dir.'),
  ('DNA polimerazın yeni nükleotitleri yalnızca hangi uca ekleyebildiği aşağıdakilerden hangisidir?', 'Uzayan zincirin 3\' ucuna', ['Uzayan zincirin 5\' ucuna', 'Kalıp zincirin 3\' ucuna', 'Zincirin iki ucuna eşit olarak'], 'DNA polimeraz yeni nükleotiti var olan zincirin 3\'-OH grubuna bağlar; bu nedenle sentez yalnızca 5\'→3\' yönünde ilerler.'),
  ('DNA polimerazın sentezi başlatabilmesi için gereken kısa RNA başlatıcısını (primer) hangi enzim sentezler?', 'Primaz', ['Ligaz', 'Helikaz', 'Ters transkriptaz'], 'DNA polimeraz sıfırdan zincir başlatamaz; primazın yaptığı kısa RNA parçasının 3\' ucuna nükleotit ekler.'),
  ('Kromozom uçlarındaki tekrarlı dizileri uzatarak eşlenme sırasında uçların kısalmasını dengeleyen enzim hangisidir?', 'Telomeraz', ['Helikaz', 'Restriksiyon enzimi', 'DNA ligaz'], 'Telomeraz kendi RNA kalıbını kullanarak telomer dizilerini ekler; kök hücrelerde ve çoğu kanser hücresinde etkindir.'),
  ('RNA\'nın DNA\'ya göre kimyasal olarak daha kararsız olmasının başlıca nedeni aşağıdakilerden hangisidir?', 'Riboz şekerinin 2\' karbonunda bir hidroksil grubu taşıması', ['RNA\'da hiç fosfat bulunmaması', 'RNA\'nın yalnızca pürin bazları içermesi ve bu bazların ışıkla kolayca parçalanması', 'RNA\'nın her zaman çift zincirli olması'], 'Ribozun 2\'-OH grubu komşu fosfodiester bağına saldırarak zinciri kolayca kırabilir; deoksiribozda bu grup yoktur.'),
  ('Ökaryotik mRNA\'nın çekirdekten çıkmadan önce geçirdiği işlemlerden biri hangisidir?', '5\' ucuna kep, 3\' ucuna poli-A kuyruğu eklenmesi', ['Bütün eksonlarının çıkarılması', 'Timin bazlarının eklenmesi', 'Ribozom tarafından çift zincirli hâle getirilmesi'], 'Kep ve poli-A kuyruğu mRNA\'yı yıkımdan korur, çekirdekten çıkışını ve ribozoma bağlanmasını kolaylaştırır.'),
  ('Prokaryotlarda translasyonun, transkripsiyon henüz bitmeden başlayabilmesinin nedeni nedir?', 'Çekirdek zarı bulunmadığı için iki olayın aynı bölmede gerçekleşmesi', ['Prokaryotlarda ribozom bulunmaması', 'Prokaryotik mRNA\'nın intron taşıması', 'Prokaryotlarda RNA polimerazın ribozoma kalıcı olarak bağlı bulunması'], 'Prokaryotlarda DNA sitoplazmadadır; mRNA\'nın 5\' ucu sentezlenirken ribozomlar bağlanıp okumaya başlayabilir.'),
  ('DNA polimerazdan farklı olarak RNA polimeraz için hangisi doğrudur?', 'Sentezi başlatmak için bir primere ihtiyaç duymaz.', ['Yalnızca 3\'→5\' yönünde sentez yapar.', 'Kalıp olarak DNA yerine yalnızca RNA zincirlerini kullanır.', 'Sentezde deoksiribonükleotit kullanır.'], 'RNA polimeraz promotöre bağlanıp ilk nükleotitten itibaren zinciri kendisi başlatabilir; sentez yine 5\'→3\' yönündedir.'),
  ('Bir insan geninin bakteriye aktarıldığında aynı proteini ürettirebilmesi genetik kodun hangi özelliğine dayanır?', 'Kodun neredeyse bütün canlılarda ortak olmasına', ['Kodun yalnızca 20 kodondan oluşması ve her kodonun bir amino aside karşılık gelmesine', 'Kodonların örtüşerek okunmasına', 'Kodun her canlıda farklı olmasına'], 'Genetik kod hemen hemen evrenseldir; aynı kodonlar bütün canlılarda büyük ölçüde aynı amino asitleri belirtir.'),
  ('Aşağıdaki kodonlardan hangisi herhangi bir amino asidi kodlamaz?', 'UAG', ['AUG', 'UGG', 'GAG'], 'UAA, UAG ve UGA dur kodonlarıdır; hiçbir tRNA bunlara karşılık gelmez ve salınma faktörleri sentezi sonlandırır.'),
  ('Ribozomda peptit bağı oluşumunu asıl katalizleyen molekül hangisidir?', 'Büyük alt birimdeki rRNA', ['mRNA\'nın kep yapısı', 'Sitoplazmadaki ATP sentaz', 'tRNA\'nın antikodonu'], 'Peptidil transferaz etkinliği büyük alt birimdeki rRNA\'dan kaynaklanır; ribozom bu yönüyle bir ribozimdir.'),
  ('Ribozomun A bölgesine dur kodonu geldiğinde hangi olay gerçekleşir?', 'Salınma faktörü bağlanır ve polipeptit tRNA\'dan ayrılır.', ['Metiyonin taşıyan tRNA bağlanır.', 'Ribozom geri dönerek mRNA\'yı başlama kodonundan itibaren yeniden okur.', 'mRNA\'ya yeni bir kep eklenir.'], 'Dur kodonunu tanıyan tRNA yoktur; salınma faktörü bağlanınca polipeptit serbest kalır ve ribozom alt birimleri ayrılır.'),
  ('Bakterilerde lac operonu modelini geliştirerek 1965 Nobel Fizyoloji veya Tıp Ödülü\'nü paylaşan bilim insanları kimlerdir?', 'François Jacob ve Jacques Monod', ['Alfred Hershey ve Martha Chase', 'Watson ve Crick', 'Meselson ve Stahl'], 'Jacob ve Monod, E. coli\'de laktoz yıkımı genlerinin birlikte nasıl açılıp kapandığını açıklayan operon modelini 1961\'de yayımladı.'),
  ('E. coli\'nin bulunduğu ortama laktoz eklendiğinde lac operonu genlerinin okunmaya başlamasının doğrudan nedeni nedir?', 'Laktozdan türeyen allolaktozun represöre bağlanıp onu operatörden ayırması', ['Laktozun RNA polimerazı parçalaması', 'Laktozun operatör dizisine bağlanıp bu diziyi kalıcı olarak değiştirerek açık tutması', 'Laktozun ribozom sayısını azaltması'], 'Allolaktoz represörün biçimini değiştirir; operatörden ayrılan represör artık transkripsiyonu engelleyemez.'),
  ('Triptofan operonunun "baskılanabilir" olarak nitelendirilmesinin nedeni nedir?', 'Ortamda triptofan bolken genlerin kapanması', ['Ortamda triptofan bolken genlerin açılması', 'Genlerin hiçbir koşulda ifade edilmemesi ve enzimlerin dışarıdan alınması', 'Genlerin yalnızca laktoz varken açılması'], 'Triptofan yardımcı baskılayıcı olarak represörü etkinleştirir; ürün bolken onu üreten enzimlerin sentezi durur.'),
  ('DNA\'daki sitozin bazlarına metil grubu eklenmesi genellikle gen ifadesini nasıl etkiler?', 'İlgili genin susturulmasına yol açar.', ['Genin her zaman daha çok okunmasını sağlar.', 'Gen dizisini kalıcı olarak değiştirir.', 'Genin başka kromozoma taşınmasına yol açar.'], 'Promotör bölgelerindeki CpG metilasyonu transkripsiyon faktörlerinin bağlanmasını zorlaştırır ve kromatini sıkılaştırır.'),
  ('Histon proteinlerine asetil grubu eklenmesinin gen ifadesi üzerindeki tipik etkisi nedir?', 'Kromatini gevşeterek transkripsiyonu kolaylaştırmak', ['DNA\'yı kesip parçalara ayırmak', 'Kromatini sıkıştırarak bölgedeki genleri kalıcı olarak susturmak', 'Histonları hücre dışına taşımak'], 'Asetilasyon histonların pozitif yükünü azaltır, DNA\'yla etkileşimi zayıflar ve kromatin okunabilir hâle gelir.'),
  ('Küçük RNA\'ların (mikroRNA) gen ifadesini düzenleme biçimi hangisidir?', 'Hedef mRNA\'ya bağlanıp onun yıkımını ya da çevrilmesini engellemek', ['DNA\'ya yeni genler eklemek', 'Kromozom sayısını artırarak hücredeki bütün genlerin ifadesini yükseltmek', 'Ribozomun yapısını kalıcı olarak değiştirmek'], 'mikroRNA\'lar tamamlayıcı mRNA\'ları tanıyarak translasyonu baskılar ya da mRNA\'nın parçalanmasını sağlar.'),
  ('Çift zincirli RNA\'nın gen susturmasına yol açtığını (RNA girişimi) keşfederek 2006 Nobel ödülünü alan bilim insanları kimlerdir?', 'Andrew Fire ve Craig Mello', ['Jacob ve Monod', 'Nirenberg ve Khorana', 'Jennifer Doudna ve Emmanuelle Charpentier'], 'Fire ve Mello 1998\'de nematodlarda çift zincirli RNA\'nın tamamlayıcı mRNA\'yı susturduğunu gösterdi.'),
  ('EcoRI enziminin tanıdığı 5\'-GAATTC-3\' dizisi tamamlayıcı zincirde de 5\'→3\' yönünde aynı okunur. Bu tür dizilere ne ad verilir?', 'Palindromik dizi', ['Tekrarlı telomer dizisi', 'Promotör bölgesi', 'Okazaki dizisi'], 'Restriksiyon enzimlerinin tanıma bölgeleri çoğunlukla palindromiktir; iki zincir aynı yönde okunduğunda aynı diziyi verir.'),
  ('Aynı restriksiyon enzimiyle kesilen bir plazmit ile insan DNA\'sı parçasının kolayca birleşebilmesini sağlayan özellik hangisidir?', 'Uçlarda birbirini tamamlayan yapışkan uçların oluşması', ['Plazmidin insan kromozomlarıyla aynı büyüklükte olması', 'İnsan DNA\'sının bakteri DNA\'sından daha kısa olması', 'Enzimin iki DNA\'yı kendiliğinden kalıcı olarak bağlaması'], 'Yapışkan uçlar baz eşleşmesiyle geçici olarak birleşir; ardından DNA ligaz şeker-fosfat bağlarını kurarak birleşimi kalıcı hâle getirir.'),
  ('PCR\'da kullanılan Taq DNA polimerazın tercih edilmesinin nedeni nedir?', 'Yüksek sıcaklıklarda bozulmadan çalışabilmesi', ['DNA\'yı belirli dizilerden kesebilmesi', 'Primer gerektirmeden RNA sentezlemesi', 'Yalnızca düşük sıcaklıklarda etkin olup tepkimeyi soğukta yürütebilmesi'], 'Taq polimeraz sıcak kaynaklarda yaşayan Thermus aquaticus bakterisinden elde edilir; her döngüde 90°C\'yi aşan sıcaklıklara dayanır.'),
  ('Çift zincirli tek bir hedef DNA molekülüyle başlayan ideal bir PCR\'da 10 döngü sonunda kaç hedef DNA molekülü elde edilir?', '1024', ['20', '100', '512'], 'Her döngüde DNA miktarı iki katına çıkar: 2¹⁰ = 1024.'),
  ('PCR döngüsünün ilk basamağında karışımın 94–95°C\'ye kadar ısıtılmasının amacı nedir?', 'DNA\'nın iki zincirini birbirinden ayırmak', ['Primerlerin kalıp zincirdeki tamamlayıcı dizilere bağlanmasını sağlamak', 'Yeni nükleotitleri eklemek', 'Polimerazı etkisizleştirmek'], 'Yüksek sıcaklıkta hidrojen bağları kopar ve tek zincirler kalıp olarak açığa çıkar; ardından soğutmayla primerler bağlanır, 72°C\'de uzama olur.'),
  ('Jel elektroforezinde DNA parçalarının pozitif kutba doğru ilerlemesinin nedeni nedir?', 'Fosfat gruplarından dolayı negatif yüklü olmaları', ['Jelin DNA moleküllerini kendiliğinden çekmesi', 'Bazlarının pozitif yüklü olması nedeniyle jelin içinde itilmeleri', 'DNA\'nın sudan hafif olması'], 'Şeker-fosfat omurgasındaki fosfatlar DNA\'ya negatif yük kazandırır; elektrik alanında DNA anoda doğru göç eder.'),
  ('Aynı jelde yürütülen 500, 2000 ve 8000 baz çiftlik üç DNA parçasından hangisi yükleme kuyucuğundan en uzağa gider?', '500 baz çiftlik parça', ['2000 baz çiftlik parça', '8000 baz çiftlik parça', 'Üçü de eşit uzaklığa gider'], 'Jelin gözenekleri arasında küçük parçalar daha kolay ilerler; en kısa parça en uzağa gider.'),
  ('Zincir sonlandırıcı dideoksinükleotitlerle DNA dizileme yöntemini 1977\'de geliştiren ve iki kez Nobel ödülü almış bilim insanı kimdir?', 'Frederick Sanger', ['Kary Mullis', 'John Craig Venter', 'Walter Gilbert'], 'Sanger 1958\'de insülinin amino asit dizisi, 1980\'de DNA dizileme yöntemi için Nobel Kimya Ödülü aldı.'),
  ('Somatik hücre çekirdek aktarımıyla elde edilen bir klon ile çekirdek verici arasında görünüşte bazı küçük farkların bulunabilmesinin nedenlerinden biri hangisidir?', 'Mitokondriyal DNA ve gelişim ortamının farklı olabilmesi', ['Klon ile vericinin çekirdek DNA\'larının birbirinden tamamen farklı olması', 'Klonların her zaman haploit olması', 'Klonların eşey kromozomu taşımaması'], 'Çekirdek genomu aynı olsa da mitokondriler yumurtadan gelir; rahim ortamı ve çevre koşulları da fenotipi etkiler.'),
  ('Bt mısırı ve Bt pamuğu gibi bitkilerin bazı zararlı böceklere karşı dayanıklı olmasının nedeni nedir?', 'Bakteriden aktarılan bir genle böceklere zehirli protein üretmeleri', ['Yapraklarının yapışkan tüylerle böcekleri fiziksel olarak tutup sindirebilmesi', 'Kökleriyle böceklere saldıran mantarlar barındırmaları', 'Sürekli böcek ilacı püskürtülerek yetiştirilmeleri'], 'Bacillus thuringiensis\'ten aktarılan Cry genleri belirli böceklerin bağırsağında etkili bir toksin üretir.'),
  ('Gen tedavisinde genin hücrelere taşınması için zararsız hâle getirilmiş virüslerin sıkça kullanılmasının nedeni nedir?', 'Virüslerin genetik maddelerini hücrelere doğal olarak aktarabilmesi', ['Virüslerin hücrelerden çok daha büyük olması', 'Virüslerin protein sentezini konak ribozomu yerine kendi ribozomlarıyla yapabilmesi', 'Virüslerin bağışıklık sistemini her zaman güçlendirmesi'], 'Virüsler hücreye girip genomlarını aktarmak için evrimleşmiştir; hastalık yapan genleri çıkarılıp yerine tedavi edici gen konur.'),
  ('CRISPR-Cas9 sisteminde Cas9 enziminin DNA\'yı hangi noktadan keseceğini belirleyen molekül nedir?', 'Kılavuz RNA', ['Restriksiyon enzimi', 'Ters transkriptaz ve onun yaptığı cDNA', 'Plazmitteki antibiyotik direnç geni'], 'Kılavuz RNA hedef DNA dizisiyle tamamlayıcı eşleşir ve Cas9\'u o bölgeye yönlendirir; Cas9 çift zinciri keser.'),
  ('CRISPR-Cas9 genom düzenleme yöntemini geliştirmeleriyle 2020 Nobel Kimya Ödülü\'nü alan bilim insanları kimlerdir?', 'Emmanuelle Charpentier ve Jennifer Doudna', ['Andrew Fire ve Craig Mello', 'Kary Mullis ve Michael Smith', 'Shinya Yamanaka ve John B. Gurdon'], 'Charpentier ve Doudna 2012\'de Cas9\'un programlanabilir bir DNA makası olarak kullanılabileceğini gösterdi.'),
  ('DNA parmak izi analizlerinde bireyleri birbirinden ayırt etmek için en çok yararlanılan DNA bölgeleri hangileridir?', 'Kişiden kişiye uzunluğu değişen kısa ardışık tekrarlar', ['Bütün insanlarda baz dizisi tamamen aynı olan ribozomal RNA genleri', 'Yalnızca Y kromozomunda bulunan tek bir gen', 'Mitokondride bulunan ATP sentaz geni'], 'Kısa ardışık tekrarların (STR) kaç kez tekrarlandığı bireyler arasında çok değişkendir; birkaç bölge birlikte incelenince eşleşme olasılığı son derece düşer.'),
  ('Bir babalık testinde çocuğun DNA bantlarından annesinde bulunmayanların hepsi aday babada da bulunmuyor. Bu sonuçtan hangi çıkarım yapılır?', 'Aday baba çocuğun biyolojik babası olamaz.', ['Aday baba kesinlikle çocuğun babasıdır.', 'Çocuk, annenin değil başka bir kadının biyolojik çocuğudur.', 'Test sonucunda bir yorum yapılamaz.'], 'Çocuğun anneden gelmeyen alelleri biyolojik babadan gelmiş olmalıdır; aday babada bu bantlar yoksa babalık dışlanır.'),
  ('Kişilerin genetik test sonuçlarıyla ilgili olarak biyoetik açıdan en çok önemsenen ilke hangisidir?', 'Bilgilerin gizliliği ve kişinin rızası olmadan paylaşılmaması', ['Test sonuçlarının herkesin erişimine açık bir listede yayımlanması', 'İşverenlerin işe alımda bütün adaylara genetik testi zorunlu tutabilmesi', 'Sonuçların kişiye hiçbir zaman bildirilmemesi'], 'Genetik bilgi kişiye ve ailesine özeldir; ayrımcılık riskine karşı gizlilik ve bilgilendirilmiş onam temel ilkelerdir.'),
  ('İnsan Genom Projesi hangi yıllar arasında yürütülmüş ve tamamlandığı duyurulmuştur?', '1990–2003', ['1953–1966', '1975–1982', '2008–2015'], 'Proje 1990\'da başladı; insan genomunun dizisinin büyük ölçüde tamamlandığı 2003\'te ilan edildi.'),
  ('İnsanın haploit genomu yaklaşık kaç baz çiftinden oluşur?', '3 milyar', ['3 milyon', '30 milyar', '300 milyon'], 'İnsan haploit genomu yaklaşık 3,1 milyar baz çifti içerir; diploit hücrede bu miktar iki katıdır.'),
  ('Gen sayısı ile organizmanın karmaşıklığı arasındaki ilişki için hangisi doğrudur?', 'Gen sayısı tek başına canlının karmaşıklığını göstermez.', ['En çok gene sahip canlılar her zaman en karmaşık canlılardır.', 'Bütün omurgalıların gen sayısı tamamen aynıdır.', 'Bakterilerin gen sayısı memelilerden fazladır.'], 'İnsanın gen sayısı bazı bitkilerinkinden azdır; karmaşıklık gen düzenlenmesi ve alternatif kırpılmayla da ilişkilidir.'),
  ('Hardy-Weinberg dengesindeki bir popülasyonda çekinik fenotipli bireylerin oranı %16\'dır. Bu popülasyonda heterozigot bireylerin oranı nedir?', '%48', ['%24', '%36', '%84'], 'q² = 0,16 ise q = 0,4 ve p = 0,6\'dır; heterozigot oranı 2pq = 2 × 0,6 × 0,4 = 0,48.'),
  ('1000 bireylik bir popülasyonda 360 AA, 480 Aa ve 160 aa birey bulunmaktadır. A alelinin frekansı kaçtır?', '0,6', ['0,36', '0,4', '0,48'], 'Toplam 2000 alel vardır; A sayısı 2 × 360 + 480 = 1200\'dür. 1200 / 2000 = 0,6.'),
  ('Hardy-Weinberg ilkesinin evrim çalışmalarındaki asıl önemi nedir?', 'Evrimin işlemediği bir karşılaştırma modeli sunması', ['Doğadaki bütün popülasyonların her zaman dengede olduğunu kanıtlaması', 'Mutasyon hızını doğrudan ölçmesi', 'Türleşmenin nasıl olduğunu tek başına açıklaması'], 'Gözlenen frekanslar beklenenden saparsa popülasyonda seçilim, göç, sürüklenme gibi evrimsel bir etkenin işlediği anlaşılır.'),
  ('Popülasyonlarda alel frekanslarının denge koşulları altında kuşaklar boyu değişmeyeceğini 1908\'de birbirinden bağımsız olarak gösteren iki bilim insanından biri İngiliz matematikçi Hardy\'dir. Diğeri kimdir?', 'Wilhelm Weinberg', ['Ronald Fisher', 'Sewall Wright', 'John Burdon Sanderson Haldane'], 'Alman hekim Wilhelm Weinberg ve Godfrey Hardy aynı yıl ilkeyi bağımsız olarak ortaya koydu.'),
  ('İki komşu popülasyon arasında bireylerin düzenli olarak göç etmesi, bu popülasyonların gen havuzlarını zamanla nasıl etkiler?', 'Gen havuzlarını birbirine benzetir.', ['Gen havuzlarını hızla farklılaştırır.', 'Mutasyon hızını artırır.', 'Gen havuzlarını hiç etkilemez.'], 'Gen akışı popülasyonlar arasında alel alışverişi sağlar ve farklılaşmayı azaltır.'),
  ('Akraba evliliklerinin çekinik kalıtsal hastalıkların görülme sıklığını artırmasının nedeni nedir?', 'Ortak atadan gelen aynı çekinik alelin çocukta iki kopya olma olasılığının artması', ['Akraba evliliklerinde eşey hücrelerindeki mutasyon hızının birkaç kat yükselmesi ve yeni alellerin oluşması', 'Baskın alellerin akrabalarda kaybolması', 'Çocukların kromozom sayısının değişmesi'], 'Akrabalar ortak atalarından aynı alelleri taşıma olasılığı yüksek kişilerdir; bu durum homozigotluğu artırır.'),
  ('Zürafanın uzun boynu Lamarck ve Darwin tarafından farklı biçimde açıklanır. Darwin\'in açıklamasına uygun olan ifade hangisidir?', 'Doğuştan boynu biraz uzun olanlar daha çok hayatta kalıp üremiş, özellik yaygınlaşmıştır.', ['Zürafalar yüksek dallara uzandıkça boyunları uzamış ve kazanılan bu uzunluk yavrularına geçmiştir.', 'Zürafaların boyunları her kuşakta kendiliğinden uzamıştır.', 'Kısa boyunlu zürafalar bilerek uzun boyunlu eş seçmiştir.'], 'Darwin\'e göre popülasyonda kalıtsal çeşitlilik vardır; çevreye daha uyumlu bireyler daha çok yavru bırakır. Lamarck ise kullanımla kazanılan değişikliğin kalıtıldığını savunur.'),
  ('Kuyruğu kesilen farelerin yavrularının kuyruklu doğması, kuşaklar boyunca sürdürülen deneylerde de değişmez. Bu sonuç hangi görüşe karşı kanıt oluşturur?', 'Kazanılmış özelliklerin kalıtılabileceği görüşüne', ['Doğal seçilim görüşüne', 'Mendel\'in ayrılma ilkesine ve alellerin gametlere dağılmasına', 'Mutasyonların rastgele olduğu görüşüne'], 'August Weismann\'ın deneyleri, vücut hücrelerinde oluşan değişikliklerin eşey hücrelerine geçmediğini göstererek Lamarckçı kalıtıma karşı kanıt sundu.'),
  ('Jeolog Charles Lyell\'in, yeryüzünün bugün de işleyen yavaş süreçlerle uzun zamanda biçimlendiği görüşü Darwin\'i nasıl etkilemiştir?', 'Canlıların da uzun sürede küçük değişimlerle evrimleşebileceğini düşündürmüştür.', ['Türlerin hiç değişmediğini kanıtlamıştır.', 'Mutasyonların nedenini açıklamıştır.', 'DNA\'nın yapısını ve kalıtımın moleküler temelini keşfetmesine doğrudan yol açmıştır.'], 'Tekdüzecilik (üniformitaryanizm) ilkesi, Dünya\'nın çok yaşlı olduğunu ve küçük değişimlerin büyük sonuçlar doğurabileceğini gösterdi.'),
  ('Erkek tavus kuşlarının iri ve gösterişli kuyruklarının, avcılara yakalanma riskini artırmasına karşın korunmasının en iyi açıklaması hangisidir?', 'Dişilerin bu kuyruğa sahip erkekleri eş olarak seçmesi', ['Kuyruğun uçmayı kolaylaştırması', 'Kuyruğun vücut ısısını düzenlemesi', 'Gösterişli kuyruğun yalnızca ileri yaşlarda ve üreme döneminden sonra oluşması'], 'Eşeysel seçilimde üreme başarısını artıran özellikler, hayatta kalmayı zorlaştırsa da seçilir.'),
  ('Bir hastanede sık antibiyotik kullanılan servislerde dirençli bakterilerin oranı artıyor. Bu durumla ilgili en doğru yorum hangisidir?', 'Antibiyotik, popülasyonda zaten var olan dirençlileri seçmiştir.', ['Antibiyotik, bakterilere direnç kazanmayı öğretmiştir.', 'Bakteriler ihtiyaç duydukları için bilinçli olarak mutasyon üretmiştir.', 'Antibiyotik bütün bakterileri eşit oranda öldürmüştür.'], 'Direnç mutasyonları antibiyotikten bağımsız ortaya çıkar; antibiyotik duyarlıları öldürdüğü için dirençliler çoğalır.'),
  ('Bazı balina türlerinin vücutlarının içinde arka bacak ve kalça kemiklerinin küçük kalıntılarının bulunması en iyi nasıl açıklanır?', 'Balinaların dört ayaklı kara memelilerinden evrimleşmiş olması', ['Balinaların gelecekte karada yaşayacak olması', 'Bu kemiklerin yüzmeyi doğrudan sağlaması', 'Balinaların karada yaşamayan ilkel balık gruplarından doğrudan türemiş olması'], 'Körelmiş arka bacak kemikleri balinaların karada yaşayan atalardan geldiğine işaret eder; fosil kayıtları da bunu destekler.'),
  ('2004\'te Kanada\'nın Arktik bölgesinde bulunan Tiktaalik roseae fosili hangi evrimsel geçişe ışık tutar?', 'Balıklardan dört ayaklı kara omurgalılarına geçiş', ['Sürüngenlerden kuşlara geçiş', 'Kara memelilerinden denizde yaşayan balinalara ve yunuslara geçiş', 'Maymunlardan insanlara geçiş'], 'Tiktaalik yüzgeçlerinde bilek benzeri kemikler, boynu ve akciğere benzer yapılar taşıyan bir balıktır; sudan karaya geçişin ara formudur.'),
  ('Kayaç katmanları bozulmamış bir bölgede alt katmanlarda yalnızca deniz omurgasızlarının, üst katmanlarda ise memeli fosillerinin bulunması neyi gösterir?', 'Memelilerin deniz omurgasızlarından sonra ortaya çıktığını', ['Memelilerin deniz omurgasızlarından çok daha önce ortaya çıkıp onlara dönüştüğünü', 'İki grubun aynı anda yaşadığını', 'Fosillerin rastgele dağıldığını'], 'Bozulmamış tortul kayaçlarda alttaki katmanlar daha eskidir; buna üst üste gelme ilkesi denir.'),
  ('Fosil kayıtlarının eksik olmasının en önemli nedeni aşağıdakilerden hangisidir?', 'Fosilleşmenin ancak özel koşullarda ve az sayıda canlıda olması', ['Eski canlıların hiçbir zaman kemik, kabuk ya da diş gibi sert dokulara sahip olmaması', 'Bütün fosillerin bulunmuş olması', 'Fosillerin yalnızca okyanus tabanında oluşması'], 'Ölen canlıların çoğu ayrışır; hızlı gömülme, oksijensiz ortam ve sert doku gibi koşullar gerektiğinden fosilleşme nadirdir.'),
  ('İnsan genomunda işlevini yitirmiş gen kalıntıları (psödogenler) bulunur; örneğin C vitamini sentezinde görev alan GULO geni insanda işlevsizdir. Bunun evrimsel anlamı nedir?', 'Atalarımızda işlevli olan bir genin bozulmuş kalıntısını taşıdığımız', ['İnsanların ilerleyen kuşaklarda bu gen sayesinde C vitaminini yeniden üretmeye başlayacağı', 'Bu genin yalnızca bitkilerde bulunduğu', 'Psödogenlerin sonradan dışarıdan eklendiği'], 'Pek çok memeli C vitaminini kendisi üretir; primatlarda bu gen mutasyonlarla işlevsiz kalmış, kalıntısı genomda durmaktadır.'),
  ('Avustralya\'da keseli memelilerin çok çeşitlenmiş olması, diğer kıtalarda ise plasentalı memelilerin baskın olması en iyi hangi evrim kanıtıyla açıklanır?', 'Biyocoğrafya', ['Karşılaştırmalı embriyoloji', 'Körelmiş organlar', 'Radyometrik tarihlendirme'], 'Avustralya uzun süre diğer kıtalardan yalıtılmış kalmış; keseliler burada rakipsiz çeşitlenmiştir. Türlerin coğrafi dağılımı evrimsel geçmişlerini yansıtır.'),
  ('Okyanus adalarındaki türlerin çoğunlukla dünyanın başka yerlerindeki benzer iklimli adalardan çok en yakın anakaradaki türlere benzemesi neyi gösterir?', 'Ada türlerinin yakın anakaradan gelen atalardan türediğini', ['Türlerin yalnızca iklime göre her adada ayrı ayrı ve birbirinden bağımsız oluştuğunu', 'Adaların hiç canlı barındırmadığını', 'Bütün adaların aynı anda oluştuğunu'], 'Darwin\'in de dikkat çektiği bu örüntü, ada canlılarının en yakın kaynaktan gelip yerinde farklılaştığını gösterir.'),
  ('Ateş böceği türlerinin her birinin kendine özgü ışık yanıp sönme düzeniyle eş araması hangi tür yalıtıma örnektir?', 'Davranışsal yalıtım', ['Habitat (yaşam alanı) yalıtımı', 'Mekanik yalıtım', 'Melez çöküşü'], 'Kur sinyalleri türe özgüdür; farklı türün sinyali eş olarak tanınmaz.'),
  ('Aşağıdakilerden hangisi zigot oluştuktan sonra etkili olan bir üreme yalıtımı mekanizmasıdır?', 'Melez bireylerin kısır olması', ['Türlerin farklı mevsimlerde çiftleşmesi', 'Eşey organlarının uyumsuz olması', 'Kur davranışlarının farklı olması'], 'Melez kısırlığı, melez canlılığının azalması ve melez çöküşü zigot sonrası mekanizmalardır; diğerleri döllenmeyi önler.'),
  ('Bazı orkide türlerinin yalnızca belirli bir güve türünün uzun hortumuyla tozlaşabilecek derin nektarlıklara sahip olması hangi sürecin sonucudur?', 'Birlikte evrim', ['Yakınsak evrim', 'Genetik darboğaz', 'Kurucu etkisi'], 'Etkileşen iki tür birbirinin evriminde seçilim baskısı oluşturur; çiçeğin nektarlığı ile tozlaştırıcının hortumu birlikte uzar.'),
  ('Uzun süre durağan kalan türlerin kısa jeolojik dönemlerde hızlı değişim geçirdiğini öne süren evrim modeli hangisidir?', 'Kesintili denge', ['Aşamalı (gradualist) evrim', 'Kazanılmış özelliklerin kalıtımı', 'Tekdüzecilik'], 'Eldredge ve Gould\'un 1972\'de önerdiği model, fosil kayıtlarında ara formların neden seyrek göründüğünü açıklamaya çalışır.'),
  ('Bir canlı grubunun kitlesel yok oluştan sonra hızla çeşitlenmesine en iyi örnek hangisidir?', 'Dinozorların yok olmasından sonra memelilerin çeşitlenmesi', ['Galápagos ispinozlarının gagalarının küçülmesi', 'Sanayi bölgelerinde güvelerin kararması', 'Antibiyotik kullanılan hastanelerde dirençli bakteri oranının hızla artması'], 'Kretase sonundaki yok oluş birçok ekolojik nişi boşalttı; memeliler bu nişlere yayılarak hızla çeşitlendi.'),
  ('Kuşların tüylerinin başlangıçta ısı yalıtımı için evrimleşip daha sonra uçuşta kullanılması hangi kavrama örnektir?', 'Ön uyum (eksaptasyon)', ['Körelme (rudimentasyon)', 'Analoji', 'Yapay seçilim'], 'Bir işlev için evrimleşmiş bir yapının sonradan farklı bir işlev üstlenmesine eksaptasyon denir.'),
  ('Miller ve Urey\'nin 1953\'te yaptığı deneyde metan, amonyak, hidrojen ve su buharından oluşan bir karışıma elektrik kıvılcımı uygulanmasıyla ne elde edilmiştir?', 'Amino asitler gibi organik moleküller', ['Canlı bakteri hücreleri', 'Çift sarmal yapıda, tamamen oluşmuş DNA molekülleri', 'Serbest oksijen gazı'], 'Deney, ilkel Dünya\'yı taklit ettiği varsayılan koşullarda cansız maddelerden yaşamın yapı taşlarının oluşabileceğini gösterdi.'),
  ('İlk canlılar ortaya çıktığında Dünya atmosferinin günümüzden en önemli farkı neydi?', 'Serbest oksijenin neredeyse hiç bulunmaması', ['Azot gazının hiç olmaması', 'Ozon tabakasının bugünkünden çok daha kalın olması ve UV\'yi tümüyle süzmesi', 'Su buharının bulunmaması'], 'Atmosferde serbest O₂ ancak fotosentetik siyanobakterilerin milyonlarca yıllık etkinliğiyle, yaklaşık 2,4 milyar yıl önce birikmeye başladı.'),
  ('Sibirya\'daki donmuş topraklarda yumuşak dokuları ve kılları korunmuş mamutların bulunabilmesinin nedeni nedir?', 'Sürekli donmuş ortamın ayrışmayı durdurması', ['Mamutların kemiklerinin taşa dönüşmesi', 'Mamutların kehribar içinde kalması', 'Mamutların yanardağ külüyle kaplanıp kemiklerinin taşlaşması'], 'Çok düşük sıcaklıkta mikroorganizmaların ayrıştırma etkinliği durur; bu nedenle yumuşak dokular da korunabilir.'),
  ('Kısa bir jeolojik dönemde yaşamış, geniş coğrafyaya yayılmış ve kolay tanınan, bu nedenle kayaçların yaşını belirlemede kullanılan fosillere ne ad verilir?', 'Kılavuz fosiller', ['Yaşayan fosiller', 'İz fosiller', 'Mikrofosiller'], 'Trilobit ve ammonit gibi kılavuz fosiller farklı bölgelerdeki katmanların aynı yaşta olduğunu saptamaya yarar.'),
  ('Karbon-14 yönteminin 100 milyon yıllık bir dinozor fosilini tarihlendirmede kullanılamamasının nedeni nedir?', 'Yarılanma ömrü kısa olduğu için ölçülebilir C-14 kalmaması', ['Dinozorların karbon içermemesi', 'C-14 miktarının zamanla artması nedeniyle ölçümün yaşı olduğundan küçük göstermesi', 'Yöntemin yalnızca bitkilere uygulanabilmesi'], 'C-14 yaklaşık 50.000 yıl içinde ölçülemeyecek düzeye iner; çok eski örnekler için potasyum-argon gibi uzun yarılanma ömürlü izotoplar kullanılır.'),
  ('Dünya tarihindeki en büyük kitlesel yok oluş olarak kabul edilen ve deniz türlerinin büyük çoğunluğunun yok olduğu olay hangi dönemlerin sınırında gerçekleşmiştir?', 'Permiyen–Triyas', ['Kretase–Paleojen', 'Ordovisiyen–Silüriyen', 'Triyas–Jura'], 'Yaklaşık 252 milyon yıl önceki Permiyen sonu yok oluşunda deniz türlerinin tahminen %90\'ından fazlası kayboldu.'),
  ('Australopithecus fosillerinde iki ayak üzerinde yürümeyi gösteren iskelet özelliklerinin küçük bir beyinle birlikte bulunması neyi gösterir?', 'İki ayaklılığın beynin büyümesinden önce evrimleştiğini', ['Beyin büyümesinin iki ayaklılıktan önce gerçekleştiğini', 'İki özelliğin tamamen aynı anda geliştiğini', 'Australopithecus\'un beyin hacmi bakımından modern insanla aynı olduğunu'], 'Fosiller, hominin soyunda dik yürüyüşün milyonlarca yıl önce, beyin hacmindeki büyük artışın ise çok daha sonra ortaya çıktığını gösterir.'),
  ('Afrika dışı kökenli günümüz insanlarının genomunda küçük bir oranda Neandertal DNA\'sı bulunması neyi gösterir?', 'Modern insanlarla Neandertallerin geçmişte melezlendiğini', ['Neandertallerin bütün modern insanların tek ve doğrudan atası olduğunu', 'Neandertallerin hâlâ yaşadığını', 'Afrikalıların Neandertallerden türediğini'], 'Svante Pääbo\'nun eski DNA çalışmaları, iki grubun Afrika dışında karşılaştığını ve çiftleştiğini ortaya koydu; Pääbo 2022\'de Nobel ödülü aldı.'),
  ('Tanzanya\'da bulunan Laetoli ayak izlerinin önemi nedir?', '3,6 milyon yıl önce iki ayaklı yürüyüşü belgelemesi', ['İlk taş aletlerin yapıldığını göstermesi', 'Bilinen en eski mağara resimlerini ve ilk sanat örneklerini barındırması', 'Ateşin ilk kez denetimli biçimde kullanıldığını göstermesi'], 'Volkanik küle basılmış izler, erken homininlerin bugünkü insanlara benzer biçimde dik yürüdüğünü doğrudan gösterir.'),
  ('Zehirli ok kurbağalarının parlak renkli derileri hangi uyum stratejisinin örneğidir?', 'Uyarıcı (aposematik) renklenme', ['Kamuflaj', 'Modifikasyon', 'Körelme'], 'Parlak renkler avcılara zehirliliği bildirir; deneyimli avcılar bu renkteki avlardan kaçınır.'),
  ('Himalaya tavşanlarında kulak, burun ve pati uçları gibi vücudun soğuk kısımlarındaki kürkün siyah, geri kalanının beyaz olması nasıl açıklanır?', 'Pigment enziminin yalnızca düşük sıcaklıkta etkin olması', ['Kulak ve pati uçlarındaki hücrelerin vücudun geri kalanından farklı genler taşıması', 'Tavşanların bu bölgeleri isle boyaması', 'Siyah tüylerin mutasyonla oluşması'], 'Pigment yapımını sağlayan enzim sıcaklığa duyarlıdır; vücut ısısının düşük olduğu uçlarda çalışır. Sırttaki tüy yolunup soğuk uygulanırsa yeniden çıkan tüy siyah olur.'),
  ('Modifikasyon ile adaptasyon arasındaki temel fark aşağıdakilerden hangisidir?', 'Modifikasyon kalıtılmaz; adaptasyon ise kalıtsal temele dayanır.', ['Modifikasyon yalnızca hayvanlarda, adaptasyon yalnızca bitkilerde görülür.', 'Modifikasyon genleri değiştirir, adaptasyon değiştirmez.', 'İkisi de yalnızca mutasyonla ortaya çıkar.'], 'Modifikasyon çevrenin fenotipe etkisidir ve genotip değişmez; adaptasyon ise doğal seçilimle yaygınlaşmış kalıtsal özelliklerdir.'),
  ('Kistik fibrozis hastalarında koyu ve yapışkan mukus birikmesinin nedeni nedir?', 'Klorür iyonu taşıyan bir zar proteininin bozuk olması', ['Alyuvarların orak biçimli olması ve kılcal damarları tıkaması', 'Pıhtılaşma faktörünün eksikliği', 'Fazladan bir kromozom bulunması'], 'CFTR genindeki mutasyon klorür kanalını bozar; salgılara su geçişi azalır ve akciğer ile pankreasta koyu mukus birikir.'),
  ('Türkiye\'de evlilik öncesi taramalarla taşıyıcılığı araştırılan ve "Akdeniz anemisi" olarak da bilinen otozomal çekinik kalıtsal kan hastalığı hangisidir?', 'Talasemi', ['Hemofili', 'Lösemi', 'Demir eksikliği anemisi'], 'Talasemide hemoglobin zincirlerinden birinin üretimi azalır; iki taşıyıcının çocuğunun hasta olma olasılığı 1/4\'tür.'),
  ('Huntington hastalığının kalıtımı için hangisi doğrudur?', 'Otozomal baskındır; hasta bir ebeveynin her çocuğu için risk %50\'dir.', ['X\'e bağlı çekinik kalıtılır ve yalnız erkeklerde görülür.', 'Otozomal çekinik kalıtılır ve yalnızca akraba evliliklerinden doğan çocuklarda görülür.', 'Mitokondriyal kalıtılır.'], '4. kromozomdaki HTT geninde CAG tekrarlarının artması hastalığa yol açar; tek kopya yeterlidir.'),
  ('Akondroplazi (bir tür cücelik) baskın kalıtılmasına karşın hastaların çoğunun sağlıklı ebeveynlerden doğmasının en olası nedeni nedir?', 'Eşey hücrelerinde yeni ortaya çıkan mutasyonlar', ['Ebeveynlerin taşıyıcı olması', 'Hastalığın X kromozomuna bağlı çekinik kalıtılması', 'Gebelikte beslenme yetersizliği'], 'Olguların büyük çoğunluğu FGFR3 genindeki yeni (de novo) mutasyonlardan kaynaklanır; bu mutasyonlar çoğunlukla babanın spermlerinde oluşur.'),
  ('Baskınlığın tam olduğu ve genlerin bağımsız açıldığı AaBb × aaBb çaprazlamasında döllerin fenotip oranı nedir?', '3 : 1 : 3 : 1', ['9 : 3 : 3 : 1', '1 : 1 : 1 : 1', '1 : 2 : 1'], 'A karakteri için 1:1, B karakteri için 3:1 açılım vardır; (1:1) × (3:1) = 3:1:3:1.'),
  ('AaBb × AaBb çaprazlamasında (genler bağımsız) bir dölün AaBb genotipinde olma olasılığı nedir?', '1/4', ['1/16', '9/16', '1/8'], 'Aa olasılığı 1/2, Bb olasılığı 1/2\'dir; 1/2 × 1/2 = 1/4.'),
  ('Erkek ve dişi ebeveynlerin rolleri değiştirilerek aynı çaprazlamanın iki kez yapılmasına ne ad verilir?', 'Resiprokal çaprazlama', ['Test çaprazlaması', 'Geri çaprazlama', 'Kendileştirme'], 'Mendel mor çiçekli bitkinin polenini beyaza, beyazınkini mora vererek sonuçların değişmediğini gördü; bu, genlerin eşeye bağlı olmadığını gösterir.'),
  ('Mendel genetiğinde F1 kuşağı ifadesi neyi tanımlar?', 'Ebeveyn kuşağının çaprazlanmasından doğan ilk döl kuşağı', ['Ebeveynlerin anne ve babalarından oluşan kuşak', 'F2 bireylerinin kendi aralarında çaprazlanmasından doğan döl kuşağı', 'Yalnızca test çaprazlamasından doğan döller'], 'P kuşağının çaprazlanmasıyla F1 (birinci filial kuşak), F1\'in kendi aralarında çaprazlanmasıyla F2 elde edilir.'),
  ('Genlerin kromozomlar üzerinde taşındığını ve mayozdaki kromozom davranışının Mendel yasalarını açıkladığını 1902–1903\'te öne süren bilim insanları kimlerdir?', 'Walter Sutton ve Theodor Boveri', ['James Watson ve Francis Crick', 'Beadle ve Tatum', 'Hardy ve Weinberg'], 'Sutton-Boveri kromozom kuramı, homolog kromozomların ayrılmasının alellerin ayrılmasıyla örtüştüğünü gösterdi.'),
  ('Farklı genotipteki iki saf hattın melezlenmesiyle elde edilen döllerin ebeveynlerinden daha verimli ve dayanıklı olmasına ne ad verilir?', 'Melez azmanlığı (heterosis)', ['Akrabalı çiftleşme çöküşü (depresyonu)', 'Genetik sürüklenme', 'Eksik penetrans'], 'Hibrit mısır çeşitleri melez azmanlığından yararlanılarak üretilir; heterozigotluk zararlı çekinik alellerin etkisini maskeler.'),
  ('Genotipi I^A I^A olan bir anne ile I^B I^B olan bir babanın bütün çocukları hangi kan grubundan olur?', 'AB', ['A', 'B', '0'], 'Her çocuk anneden I^A, babadan I^B alır; iki alel eş baskın olduğundan kan grubu AB olur.'),
  ('A kan gruplu bir anne ile B kan gruplu bir babanın 0 kan gruplu bir çocuğu doğmuştur. Ebeveynlerin genotipleri hakkında hangisi kesindir?', 'İkisi de i alelini taşır.', ['Anne homozigot, baba heterozigottur.', 'Baba homozigot, anne heterozigottur.', 'İkisi de homozigottur.'], '0 grubu ii genotiplidir; çocuk her ebeveynden bir i almış olmalıdır. Bu nedenle anne I^A i, baba I^B i\'dir.'),
  ('B kan gruplu bir kişi ABO sistemine göre alyuvar nakli için hangi kan gruplarından kan alabilir?', 'B ve 0', ['Yalnızca B', 'A ve B', 'AB ve B'], 'B grubunun plazmasında anti-A bulunur; bu nedenle A antijeni taşıyan A ve AB grupları uygun değildir.'),
  ('Renk körü bir erkek ile taşıyıcı bir kadının doğacak bir çocuğunun renk körü olma olasılığı nedir?', '1/2', ['1/4', '3/4', '1/8'], 'X^r Y × X^R X^r çaprazlamasında X^r X^r, X^R X^r, X^r Y ve X^R Y eşit olasılıklıdır; bunların ikisi renk körüdür.'),
  ('D vitaminine dirençli raşitizm X\'e bağlı baskın kalıtılır. Hasta bir erkek ile sağlıklı bir kadının çocukları için hangisi beklenir?', 'Kızların tamamı hasta, oğulların tamamı sağlıklı olur.', ['Oğulların tamamı hasta, kızların tamamı sağlıklı olur.', 'Çocukların yarısı hasta olur, eşey fark etmez.', 'Çocuklardan hasta olan bulunmaz; alel bir kuşak atlar.'], 'Baba X^H kromozomunu bütün kızlarına verir ve baskın olduğundan kızlar hastadır; oğullar babadan Y aldığı için etkilenmez.'),
  ('Avrupa kraliyet ailelerinde görülmesi nedeniyle "kraliyet hastalığı" olarak da anılan ve Kraliçe Victoria\'nın taşıyıcı olduğu bilinen hastalık hangisidir?', 'Hemofili', ['Renk körlüğü', 'Albinizm', 'Huntington hastalığı'], 'Victoria\'nın oğlu Leopold hemofiliydi; kızları aracılığıyla alel İspanya, Almanya ve Rusya kraliyet ailelerine yayıldı.'),
  ('Bir kromozom çiftinin tek kopyasının bulunduğu (2n−1) duruma ne ad verilir?', 'Monozomi', ['Trizomi', 'Poliploidi', 'Duplikasyon'], 'İnsanda canlı doğumla uyumlu tek tam monozomi X kromozomu monozomisidir (Turner sendromu).'),
  ('Trizomi 18 olarak bilinen ve genellikle ağır doğumsal anomalilerle seyreden sendrom hangisidir?', 'Edwards sendromu', ['Patau (trizomi 13) sendromu', 'Down sendromu', 'Turner sendromu'], 'Edwards sendromunda 18. kromozom, Patau sendromunda 13. kromozom üç kopya hâlinde bulunur.'),
  ('Ekmeklik buğdayın altı takım kromozom taşıması (6n) hangi olaya örnektir?', 'Poliploidi', ['Anöploidi', 'Translokasyon', 'Delesyon'], 'Ekmeklik buğday üç farklı atasal türün melezlenmesi ve kromozom takımlarının katlanmasıyla oluşmuş heksaploit bir türdür.'),
  ('Gebeliğin 15–20. haftalarında rahimdeki sıvıdan örnek alınarak bebeğin kromozomlarının incelenmesini sağlayan yöntem hangisidir?', 'Amniyosentez', ['Ultrasonografi', 'Elektrokardiyografi', 'Endoskopi'], 'Amniyon sıvısındaki fetal hücreler kültüre alınıp karyotip analizi yapılabilir.'),
  ('Kedi miyavlaması (cri du chat) sendromu hangi tür kromozom değişikliğinden kaynaklanır?', '5. kromozomun kısa kolundaki delesyon', ['21. kromozomun trizomisi', 'X kromozomunun monozomisi ve tek X taşınması', '9 ile 22 arasındaki translokasyon'], 'Bebeklerin kedi miyavlamasını andıran ağlaması nedeniyle bu adı alan sendrom, 5p bölgesinin kaybından kaynaklanır.'),
  ('DNA\'da bir pürinin başka bir pürinle (örneğin A yerine G) yer değiştirdiği nokta mutasyonuna ne ad verilir?', 'Transisyon', ['Transversiyon', 'Delesyon', 'İnversiyon'], 'Pürin–pürin ya da pirimidin–pirimidin değişimi transisyon, pürin–pirimidin değişimi transversiyondur.'),
  ('DNA polimerazın eşlenme sırasında yanlış eklenen nükleotiti fark edip hemen çıkarmasına ne ad verilir?', 'Düzeltme okuması (proofreading)', ['Transkripsiyon', 'Krossing-over (parça değişimi)', 'Ters transkripsiyon'], 'DNA polimerazın 3\'→5\' ekzonükleaz etkinliği yanlış eşleşen nükleotiti çıkarır; böylece hata oranı büyük ölçüde azalır.'),
  ('Kansere yatkınlık geni BRCA1\'de mutasyon taşıyan bir kadın için hangi ifade en doğrudur?', 'Kanser riski artmıştır, ancak kanser gelişmesi kesin değildir.', ['Kesinlikle meme kanseri olacaktır.', 'Bu mutasyonu çocuklarına aktaramaz.', 'Mutasyon yalnızca erkeklerde etkilidir, kadınlarda hiçbir risk oluşturmaz.'], 'Kalıtılan tek kopya yatkınlık yaratır; kanser için genellikle diğer kopyanın da hücrede bozulması gerekir. Mutasyon %50 olasılıkla çocuklara geçer.'),
  ('Tütün dumanında bulunan benzopiren gibi maddelerin akciğer kanseriyle ilişkisi en iyi nasıl açıklanır?', 'DNA\'ya bağlanarak mutasyonlara yol açmaları', ['Akciğer hücrelerinin kromozom sayısını yarıya indirmeleri', 'Akciğerlerdeki oksijeni tamamen tüketmeleri', 'Bağışıklık hücrelerini DNA\'sız bırakmaları'], 'Benzopiren metabolitleri DNA bazlarına kovalent bağlanır; p53 gibi genlerde biriken mutasyonlar kanser gelişimine katkı yapar.'),
  ('Prokaryot ve ökaryot DNA eşlenmesi karşılaştırıldığında hangisi doğrudur?', 'Ökaryot kromozomlarında birçok eşlenme başlangıcı bulunur.', ['Prokaryotlarda eşlenme hiçbir zaman çift yönlü değildir.', 'Ökaryot DNA\'sı yalnızca tek bir noktadan ve tek yönde eşlenmeye başlar.', 'Prokaryotlarda eşlenme için enzim gerekmez.'], 'Bakterinin halkasal kromozomunda genellikle tek bir başlangıç noktası vardır; çok uzun ökaryot kromozomları birçok noktadan aynı anda eşlenir.'),
  ('Genetik bilginin DNA\'dan RNA\'ya, RNA\'dan proteine aktarıldığını öne süren "merkezî dogma" kavramını ortaya atan bilim insanı kimdir?', 'Francis Crick', ['James Watson', 'Linus Pauling', 'Erwin Schrödinger'], 'Crick bu kavramı 1958\'de tanımladı; bilgi akışının proteinden nükleik aside geri dönmediğini vurguladı.'),
  ('HIV gibi retrovirüslerin RNA\'larından DNA sentezleyebilmesini sağlayan enzim hangisidir?', 'Ters transkriptaz', ['RNA polimeraz', 'DNA ligaz', 'Peptidil transferaz'], 'Ters transkriptaz RNA kalıbından DNA yapar; bu bulgu bilginin RNA\'dan DNA\'ya da akabileceğini göstermiştir (Temin ve Baltimore, 1970).'),
  ('Alkaptonüri gibi hastalıkları inceleyerek 1902\'de "doğuştan metabolizma hataları" kavramını ortaya atan İngiliz hekim kimdir?', 'Archibald Garrod', ['Joseph Lister', 'Edward Jenner', 'Alexander Fleming'], 'Garrod, bu hastalıkların Mendel kurallarına göre çekinik kalıtıldığını ve bir enzim eksikliğinden kaynaklandığını öne sürdü.'),
  ('mRNA\'daki 5\'-GCA-3\' kodonuna bağlanacak tRNA\'nın antikodonu 5\'→3\' yönünde nasıl yazılır?', '5\'-UGC-3\'', ['5\'-CGU-3\'', '5\'-GCA-3\'', '5\'-TGC-3\''], 'Antikodon kodona tamamlayıcı ve antiparaleldir: 3\'-CGU-5\'. Bu dizi 5\'→3\' yönünde UGC olarak yazılır.'),
  ('Bakteri ribozomlarının ökaryot ribozomlarından yapıca farklı olması tıpta nasıl kullanılır?', 'Bazı antibiyotiklerin yalnızca bakteri ribozomlarını hedeflemesi', ['Kan gruplarının belirlenmesi', 'Aşı üretiminde ribozomların hastaya doğrudan enjekte edilmesi', 'DNA parmak izi analizlerinin yapılması'], 'Streptomisin ve tetrasiklin gibi antibiyotikler 70S bakteri ribozomlarını etkiler; insan hücrelerindeki 80S ribozomları büyük ölçüde etkilenmez.'),
  ('Salgılanacak proteinlerin sentezlenirken endoplazmik retikuluma yönlendirilmesini sağlayan yapı hangisidir?', 'Proteinin başındaki sinyal peptidi', ['mRNA\'nın poli-A kuyruğu', 'tRNA\'nın antikodonu', 'Promotör bölgesindeki TATA kutusu dizisi'], 'Sinyal tanıma parçacığı yeni çıkan sinyal dizisini tanır ve ribozomu granüllü endoplazmik retikulum zarına taşır.'),
  ('Ökaryotlarda üç farklı RNA polimerazdan hangisi protein kodlayan genlerin mRNA\'larını sentezler?', 'RNA polimeraz II', ['RNA polimeraz I', 'RNA polimeraz III', 'DNA polimeraz III'], 'RNA polimeraz I büyük rRNA\'ları, II mRNA\'ları, III ise tRNA ve 5S rRNA\'yı sentezler.'),
  ('Kırpılma (splicing) sırasında intronları çıkaran, küçük çekirdek RNA\'ları ve proteinlerden oluşan yapıya ne ad verilir?', 'Splisozom (kırpılma kompleksi)', ['Proteazom', 'Nükleozom', 'Peroksizom (oksidasyon organeli)'], 'Splisozom intron-ekson sınırlarını tanır, intronu kesip çıkarır ve eksonları birleştirir.'),
  ('Yapay olarak sentezlediği tekrarlı RNA dizileriyle genetik kodun çözülmesine katkı yapan ve 1968 Nobel ödülünü Nirenberg ve Holley ile paylaşan bilim insanı kimdir?', 'Har Gobind Khorana', ['Severo Ochoa', 'Sydney Brenner', 'Frederick Sanger'], 'Khorana\'nın UCUCUC gibi tekrarlı dizilerle yaptığı deneyler kodonların üçlü ve örtüşmeyen biçimde okunduğunu doğruladı.'),
  ('Mitokondrilerde UGA kodonunun dur kodonu yerine triptofanı kodlaması genetik kod hakkında neyi gösterir?', 'Kodun neredeyse evrensel olduğunu, ancak küçük istisnalar bulunduğunu', ['Genetik kodun her hücrede rastgele değiştiğini', 'Mitokondrilerin kendi proteinlerini sentezlemeyip tümünü sitoplazmadan aldığını', 'UGA\'nın hiçbir canlıda dur kodonu olmadığını'], 'Genetik kod büyük ölçüde ortaktır; mitokondriler ve bazı tek hücrelilerdeki küçük farklar sonradan ortaya çıkmış değişikliklerdir.'),
  ('Farklı canlılardan alınan DNA parçalarını birleştirerek ilk rekombinant DNA molekülünü 1972\'de oluşturan ve 1980 Nobel Kimya Ödülü\'nü paylaşan bilim insanı kimdir?', 'Paul Berg', ['Kary Mullis', 'Craig Venter', 'Francis Collins'], 'Berg, SV40 virüsü DNA\'sını bakteriyofaj lambda DNA\'sıyla birleştirdi; bu çalışma gen mühendisliğinin başlangıcı sayılır.'),
  ('Bakterilerin dışarıdan plazmit almasını kolaylaştırmak için kalsiyum klorür ve ani ısı şoku uygulanması ya da kısa elektrik atımı verilmesi hangi işlemin parçasıdır?', 'Transformasyon', ['Transkripsiyon', 'Konjugasyon', 'Translasyon'], 'Bu uygulamalar hücre zarını geçici olarak geçirgen kılar ve bakterinin ortamdaki DNA\'yı almasını sağlar.'),
  ('Bitkilere gen aktarmak için sıkça kullanılan ve doğada bitkilerde tümör oluşturan bakteri hangisidir?', 'Agrobacterium tumefaciens', ['Escherichia coli', 'Bacillus thuringiensis', 'Streptococcus pneumoniae'], 'Bu bakterinin Ti plazmidinin bir bölümü bitki genomuna aktarılır; araştırmacılar tümör genlerini çıkarıp yerine istenen genleri yerleştirir.'),
  ('Belirli bir DNA dizisini jelde ayrılmış DNA parçaları arasında işaretli bir prob ile saptamaya yarayan yöntem hangisidir?', 'Southern blot', ['Western blot yöntemi', 'ELISA', 'Gram boyama'], 'Edwin Southern\'ın 1975\'te geliştirdiği yöntemde DNA bir zara aktarılır ve tamamlayıcı prob ile aranan dizi bulunur; RNA için Northern, protein için Western blot kullanılır.'),
  ('PCR\'da kullanılan primerlerin görevi nedir?', 'Çoğaltılacak bölgenin uçlarını belirleyip sentezi başlatmak', ['DNA\'yı belirli noktalardan kesmek', 'Yeni sentezlenen zincirleri ve Okazaki parçalarını birbirine bağlamak', 'Tepkimede çıkan ısıyı emmek'], 'Primerler hedef bölgenin iki ucundaki dizilere tamamlayıcıdır; polimeraz uzamayı bu kısa zincirlerin 3\' ucundan başlatır.'),
  ('Fareler üzerinde belirli bir genin hedefli olarak işlevsiz bırakıldığı "gen nakavt" yönteminin araştırmalardaki temel yararı nedir?', 'Genin işlevini, yokluğundaki değişikliklerden anlamak', ['Farelerin ömrünü uzatmak', 'Farelere yeni kromozomlar eklemek', 'Farelerin kürk rengini ve göz rengini kalıcı olarak değiştirip yeni ırklar üretmek'], 'Bir gen susturulduğunda ortaya çıkan fenotip, o genin normalde ne iş yaptığını gösterir; yöntem 2007 Nobel ödülüyle ödüllendirildi.'),
  ('Hepatit B aşısının rekombinant DNA teknolojisiyle nasıl üretildiği aşağıdakilerden hangisidir?', 'Yüzey proteini geninin mayaya aktarılıp proteinin ürettirilmesi', ['Canlı virüslerin hastaya doğrudan verilmesi', 'Virüsün bütün genomunun bakteride çoğaltılıp aşı olarak doğrudan enjekte edilmesi', 'Hasta kişilerin kanından virüs toplanması'], 'Mayada üretilen yüzey antijeni hastalık yapmadan bağışıklık yanıtı oluşturur; bu, rekombinant aşıların ilk örneklerindendir.'),
  ('Bazı genetiği değiştirilmiş keçilerin sütünden insan ilacı olarak kullanılan proteinlerin elde edilmesine ne ad verilir?', 'Moleküler çiftçilik (pharming)', ['Yapay seçilim', 'Hibridizasyon', 'Organik tarım (ekolojik üretim)'], 'İnsan geni meme bezinde ifade edilecek biçimde hayvana aktarılır; protein sütten saflaştırılır.'),
  ('Adli olaylarda yalnızca bir saç kökü ya da birkaç kan hücresinden DNA profili çıkarılabilmesini mümkün kılan teknik hangisidir?', 'PCR ile DNA\'nın çoğaltılması', ['Karyotip analizi', 'Kan grubu ve Rh faktörünün belirlenmesi', 'Işık mikroskobuyla inceleme'], 'Çok küçük miktardaki DNA PCR ile milyonlarca kez çoğaltılarak analiz edilebilir hâle getirilir.'),
  ('Bir kişinin genetik yapısına göre ilaç seçimi ve dozunun belirlenmesini inceleyen alana ne ad verilir?', 'Farmakogenomik', ['Paleontoloji', 'Epidemiyoloji', 'Sitoloji'], 'Aynı ilacın etkisi ve yan etkileri, ilacı işleyen enzimlerin genlerindeki farklılıklara göre kişiden kişiye değişebilir.'),
  ('Ailesinde kalıtsal hastalık bulunan çiftlere risklerini açıklayan ve seçenekleri hakkında bilgi veren uzmanlık hizmetine ne ad verilir?', 'Genetik danışmanlık', ['Psikolojik danışmanlık', 'Beslenme danışmanlığı', 'Kariyer danışmanlığı'], 'Genetik danışman soyağacı ve test sonuçlarını değerlendirerek olasılıkları açıklar; kararı aileye bırakır.'),
  ('Yapay seçilim ile doğal seçilim arasındaki temel fark aşağıdakilerden hangisidir?', 'Yapay seçilimde hangi bireylerin üreyeceğine insanın karar vermesi', ['Yapay seçilimde kalıtsal çeşitliliğe gerek olmaması ve özelliklerin sonradan kazanılması', 'Doğal seçilimin yalnızca bitkilerde işlemesi', 'Yapay seçilimin alel frekanslarını değiştirmemesi'], 'İki süreç de kalıtsal çeşitlilik üzerinde işler ve alel frekanslarını değiştirir; fark, seçimi yapanın çevre mi insan mı olduğudur.'),
  ('Darwin\'in insanın evrimini ve eşeysel seçilimi ayrıntılı olarak ele aldığı 1871 tarihli kitabı hangisidir?', 'İnsanın Türeyişi', ['Türlerin Kökeni', 'Beagle Seyahati', 'İnsan ve Hayvanlarda Duyguların İfadesi'], 'Darwin "The Descent of Man" adlı eserinde insanın diğer primatlarla ortak atadan geldiğini savundu.'),
  ('"Biyolojide hiçbir şey evrimin ışığı olmadan anlam taşımaz" sözüyle tanınan ve Modern Sentez\'in kurucularından olan genetikçi kimdir?', 'Theodosius Dobzhansky', ['Ernst Mayr', 'George Gaylord Simpson', 'Stephen Jay Gould'], 'Dobzhansky 1937\'de "Genetik ve Türlerin Kökeni" kitabıyla popülasyon genetiğini doğal tarihle birleştirdi; söz 1973 tarihli makalesinin başlığıdır.'),
  ('Peter ve Rosemary Grant\'in Galápagos\'taki Daphne Major adasında 1977 kuraklığından sonra yaptığı gözlemlerde hangi sonuç elde edilmiştir?', 'Kalın gagalı ispinozların oranının arttığı', ['Bütün ispinozların adayı terk ettiği', 'İspinozların gagalarının kuraklıkta inceldiği ve böcekle beslenmeye başladıkları', 'Kuraklığın ispinozların gaga yapısını hiç etkilemediği'], 'Kuraklıkta yalnızca iri ve sert tohumlar kaldı; bunları kırabilen kalın gagalılar hayatta kalıp üredi ve sonraki kuşakta ortalama gaga kalınlığı arttı.'),
  ('Richard Lenski\'nin 1988\'de başlattığı uzun süreli deneyde on binlerce kuşak boyunca izlenen E. coli popülasyonlarından birinin sitratı besin olarak kullanabilme yeteneği kazanması neyi gösterir?', 'Yeni özelliklerin mutasyon ve seçilimle laboratuvarda da ortaya çıkabildiğini', ['Bakterilerin hiçbir koşulda evrimleşmediğini ve dondurulmuş örneklerin değişmediğini', 'Sitratın bakterilerde doğrudan yeni genler oluşturduğunu', 'Bakterilerin istedikleri besine göre bilinçli olarak değiştiğini'], 'Deney, evrimin gözlemlenebilir bir süreç olduğunu ve yeni yeteneklerin birikimli mutasyonlarla doğabildiğini gösterdi.'),
  ('HIV ile enfekte bir hastada tek bir ilaç kullanıldığında virüsün kısa sürede ilaca direnç kazanması, birden çok ilacın birlikte kullanılmasıyla neden önlenmeye çalışılır?', 'Birkaç ilaca birden dirençli mutantın çıkma olasılığının çok düşük olması', ['Birden çok ilacın virüsün mutasyon hızını azaltması ve genomunu kararlı kılması', 'Tek bir ilacın virüse hiçbir koşulda etki etmemesi', 'İlaçların birbirlerinin yan etkilerini ortadan kaldırması'], 'Çoklu ilaç tedavisinde virüsün hayatta kalması için birkaç bağımsız direnç mutasyonunu birden taşıması gerekir.'),
  ('Ahtapot ve insan gözlerinin ikisi de mercekli "kamera" tipi olduğu hâlde ahtapot gözünde kör nokta bulunmaması neyi gösterir?', 'İki gözün bağımsız olarak evrimleştiğini', ['İki gözün ortak bir atadaki kamera gözünden türediğini', 'Ahtapotların omurgalılardan türediğini', 'İnsan gözünün ahtapot gözünden geliştiğini'], 'Benzer işlevli yapılar farklı yollarla gelişmiştir; sinirlerin retinaya bağlanma biçimindeki fark, gözlerin yakınsak evrimle oluştuğunu destekler.'),
  ('Uzak atalarda bulunup sonraki kuşaklarda kaybolmuş bir özelliğin, örneğin insan bebeklerinde kuyruk benzeri bir uzantının, nadiren yeniden ortaya çıkmasına ne ad verilir?', 'Atavizm', ['Körelme', 'Modifikasyon', 'Analoji'], 'Atavizmde baskılanmış atasal gelişim programları nadiren yeniden etkinleşir; bu, atasal genlerin genomda hâlâ bulunduğunu gösterir.'),
  ('İnsanlarda 23 çift, şempanze ve gorillerde 24 çift kromozom bulunur. İnsan 2. kromozomunun ortasında telomer dizilerine ve işlevsiz ikinci bir sentromer kalıntısına rastlanması neyi gösterir?', 'İnsan 2. kromozomunun iki atasal kromozomun kaynaşmasıyla oluştuğunu', ['İnsanların gorillerden türediğini', 'Şempanzelerin ve gorillerin ortak atalarından bir kromozomu kaybettiğini', 'Telomerlerin kromozomların ortasında oluştuğunu'], 'Kromozom uçlarına özgü diziler ortada bulunuyorsa iki kromozom uç uca birleşmiştir; bu büyük ölçüde maymunlardaki iki kromozomla örtüşür.'),
  ('Atların evriminde Eohippus\'tan (Hyracotherium) günümüz atına uzanan fosil serisinde genel eğilim hangisidir?', 'Vücudun büyümesi ve parmak sayısının teke inmesi', ['Vücudun küçülmesi ve ayak parmağı sayısının giderek artması', 'Dişlerin tamamen kaybolması', 'Bacakların kısalıp yüzgece dönüşmesi'], 'Ormandan açık çayırlara geçişle birlikte hızlı koşuya uygun tek toynaklı uzun bacaklar ve otla beslenmeye uygun dişler gelişti.'),
  ('Pakicetus ve Ambulocetus gibi fosiller hangi canlı grubunun evrimine ışık tutar?', 'Balinalar', ['Kuşlar', 'Kara bitkileri', 'Böcekler'], 'Bu fosiller karada ve kıyıda yaşayan dört ayaklı memelilerden tamamen suda yaşayan balinalara geçişi belgeler.'),
  ('1938\'de Güney Afrika açıklarında canlı olarak yakalanan ve o zamana kadar yaklaşık 66 milyon yıl önce soyu tükendiği sanılan balık hangisidir?', 'Selakant', ['Köpek balığı', 'Mersin balığı', 'Akciğerli balık'], 'Selakant "yaşayan fosil" örneği olarak bilinir; yüzgeçleri kara omurgalılarının uyluk kemiklerine benzeyen etli loblu balıklardandır.'),
  ('İki salyangoz türünün kabuklarının ters yönlerde kıvrılması nedeniyle eşey organlarının uyumsuz olması ve çiftleşememesi hangi yalıtıma örnektir?', 'Mekanik yalıtım', ['Gametik yalıtım', 'Zamansal yalıtım', 'Melez kısırlığı'], 'Mekanik yalıtımda üreme yapılarının biçimi farklı türlerin çiftleşmesini fiziksel olarak engeller.'),
  ('Bazı pirinç çeşitlerinden elde edilen birinci kuşak melezler canlı ve verimliyken, bunların ikinci kuşak döllerinin zayıf ve kısır olmasına ne ad verilir?', 'Melez çöküşü', ['Davranışsal yalıtım', 'Habitat yalıtımı', 'Heterozigot üstünlüğü'], 'Melez çöküşü zigot sonrası bir mekanizmadır; gen akışı ilk kuşakta başlasa da sonraki kuşaklarda durur.'),
  ('Dengedeki bir popülasyonda baskın alelin frekansı 0,9\'dur. Homozigot baskın bireylerin oranı yüzde kaçtır?', '%81', ['%90', '%18', '%99'], 'Homozigot baskın oranı p² = 0,9² = 0,81\'dir.'),
  ('Oparin ve Haldane\'nin 1920\'lerde öne sürdüğü "ilkel çorba" hipotezi neyi savunur?', 'Organik moleküllerin ilkel okyanuslarda enerji etkisiyle oluşması', ['Canlıların Dünya\'ya başka gezegenlerden gelen göktaşlarıyla hazır olarak taşındığını', 'İlk canlıların oksijenli solunum yaptığını', 'Yaşamın yalnızca son 10.000 yılda başladığını'], 'Hipotez, oksijensiz atmosferde yıldırım ve UV ışınlarının basit moleküllerden organik bileşikler oluşturduğunu öne sürer; Miller-Urey deneyi bunu sınadı.'),
  ('1969\'da Avustralya\'ya düşen Murchison göktaşında amino asitlerin bulunmasının önemi nedir?', 'Organik moleküllerin uzayda da cansız süreçlerle oluşabilmesi', ['Göktaşının içinde canlı bakteriler taşıması', 'Bütün canlıların uzaydan geldiğini ve Dünya\'da yaşamın kendiliğinden başlamadığını kanıtlaması', 'Dünya\'nın yaşını belirlemiş olması'], 'Göktaşındaki amino asitler, yaşamın yapı taşlarının evrende kimyasal süreçlerle yaygın biçimde oluşabileceğini düşündürdü.'),
  ('Fosillerin bulunduğu katmanın üstündeki ve altındaki katmanlarla karşılaştırılarak yalnızca "daha yaşlı" ya da "daha genç" diye sıralanmasına ne ad verilir?', 'Göreceli yaş belirleme', ['Mutlak yaş belirleme', 'Radyometrik tarihlendirme', 'Moleküler saat'], 'Göreceli yöntem kesin yıl vermez; radyometrik yöntemler ise izotopların bozunmasına dayanarak yaklaşık yaşı yıl olarak verir.'),
  ('Radyoaktif bir izotopun yarılanma ömrü ne anlama gelir?', 'Başlangıçtaki izotopun yarısının bozunması için geçen süre', ['İzotopun tamamen bozunması için geçen toplam sürenin iki katına karşılık gelen süre', 'İzotopun oluşması için gereken süre', 'Fosilin yarısının taşlaşması için geçen süre'], 'Yarılanma ömrü sabittir; örneğin her 5730 yılda C-14 miktarı yarıya iner.'),
  ('Karbonifer döneminde kanat açıklığı 60 cm\'yi bulan kızböceklerinin yaşayabilmesi en çok hangi koşulla ilişkilendirilir?', 'Atmosferdeki oksijen oranının bugünkünden yüksek olması', ['Yerçekiminin bugünkünden zayıf olması', 'Atmosferde hiç oksijen bulunmaması', 'İklimin bugünkünden çok soğuk ve kuru olması, ormanların seyrekleşmesi'], 'Böcekler oksijeni trake sistemiyle difüzyonla alır; oksijen oranı yüksek olduğunda daha büyük vücutlar desteklenebilir.'),
  ('Bakla yedikten ya da bazı ilaçları aldıktan sonra alyuvarların yıkılmasına yol açan X\'e bağlı kalıtsal enzim eksikliği hangisidir?', 'G6PD eksikliği (favizm)', ['Fenilketonüri', 'Kistik fibrozis', 'Akondroplazi (bir tür cücelik)'], 'Glikoz-6-fosfat dehidrogenaz eksikliği Akdeniz çevresinde de sık görülür; bu enzim alyuvarları oksidatif hasardan korur.'),
  ('Polidaktili (fazla parmaklılık) baskın kalıtıldığı hâlde toplumda nadir görülür. Bu durum hangi ilkeyi örnekler?', 'Bir alelin baskın olmasının sık görüleceği anlamına gelmemesi', ['Baskın alellerin her zaman yaygınlaşması', 'Çekinik alellerin popülasyonda hiç bulunmaması ve yalnızca mutasyonla ortaya çıkması', 'Fenotipin yalnızca çevreyle belirlenmesi'], 'Alel frekansı baskınlıktan bağımsızdır; baskın bir alel popülasyonda çok düşük frekansta bulunabilir.'),
];
